/* المُلهم، «تعلّم»: مكتبة المؤلفين، كتاب «برنامج الأبوة الإيجابية» */
window.HH_LIB=window.HH_LIB||{};
window.HH_LIB["abaad"]={"id":"abaad","title":"برنامج الأبوة الإيجابية","sub":"دليل حول إشراك الرجال في أدوار الوالدية","author":"مؤسسة أبعاد","coauthors":[],"translator":"زياد فران","publisher":"أبعاد، مركز الموارد للمساواة بين الجنسين، ولجنة إنقاذ الطفل الدولية","year":"2014","edition":"","series":"","lead":"دليل تدريبي عربي معدل عن برنامج Program P، يقدم توصيات للعاملين الصحيين وجلسات جماعية للآباء لإشراكهم في الحمل والولادة ورعاية الطفل وتربيته بلا عنف. «هذا الدليل هو نسخة معدلة من النسخة الأصلية لبرنامج Program P، وهو دليل لانخراط الرجال في دور الأبوة وتقديم الرعاية وصحة الأم والطفل.»","audience":"الآباء والمقبلون على الأبوة، وميسرو مجموعات الآباء والمرشدون الأسريون، والعاملون في الرعاية الصحية للأم والطفل","bio":"أبعاد هي مؤسسة مدنية، غير طائفية وغير ربحية تهدف إلى إحقاق مساواة النوع الاجتماعي لتعزيز التنمية الاقتصادية والاجتماعية المستدامة في الشرق الأوسط وشمال إفريقيا.","chapters":[{"k":"c1","t":"مقدمة: أسئلة أساسية حول دليل البرنامج","q":"لماذا يحتاج الأب إلى المشاركة في رعاية طفله منذ البداية؟","essence":"مشاركة الأب تنفع الأم والطفل والأب","kw":["الأبوة المنخرطة","صحة الأم والطفل","عقبات المشاركة"],"sections":[{"t":"فوائد مشاركة الأب","pg":10,"key":"تعتبر مشاركة الآباء ومقدمي الرعاية الذكور غير العنيفة خلال فترة ما قبل الولادة وبعدها ضرورية جدا لصحة الأم والطفل ورفاههما.","p":["وخلال ولادة الطفل، اختبرت النساء اللواتي رافقهن شريكهن خلال المخاض تجارب ولادة أكثر إيجابية"],"items":[{"h":"للأم","x":"تذكر الدراسات أن الضغط النفسي المرتبط بالحمل ينخفض حين يشارك الأب، وأن الأم التي يرافقها زوجها تحضر زيارات المتابعة أكثر، وتمر بتجربة ولادة أكثر إيجابية (ص 10)."},{"h":"للطفل","x":"مراجعة ل 16 دراسة طولية وجدت أن الأولاد الذين شارك والدهم في تربيتهم عانوا مشاكل سلوكية أقل، وكان تطورهم المعرفي وأداؤهم المدرسي أفضل (ص 12)."},{"h":"للأب نفسه","x":"الآباء المشاركون أكثر رضا عن حياتهم، ويعتنون بصحتهم أفضل، ويعيشون أطول ويمرضون أقل بحسب الدراسات المذكورة (ص 12)."},{"h":"للأسرة","x":"«عندما يشارك الآباء بشكل أكبر في حياة أبنائهم وبناتهم، من المرجح أن يحصدوا نتائج إيجابية، مثلا تحسن الصحة الجسدية والعقلية، وإنجازات أكاديمية أعلى، ومهارات معرفية واجتماعية فضلى، وثقة أكبر بالنفس» (ص 13)."}]},{"t":"التربية من دون عنف حق للطفل","pg":13,"key":"أثبتت الدراسات أن العقاب العنيف غير فعال كوسيلة للتأديب، وأنه ثمة أساليب إيجابية وغير عنيفة لتعليم الأطفال، وتوجيههم، وتأديبهم مما يساهم في نموهم الصحي ويوطد العلاقة بين الوالد والطفل","p":["كذلك، يعلم الأطفال أن العنف هو استراتيجية مقبولة ومناسبة لحل النزاعات واكتساب أفضلية على الآخر."],"items":[{"h":"انتقال العنف بين الأجيال","x":"يؤكد الدليل أن من تعرضوا للعنف في صغرهم أو شهدوه أكثر عرضة لممارسته لاحقا، دون أن يكون ذلك حتميا (ص 12)."},{"h":"دور العاملين الصحيين","x":"أمامهم فرصة فريدة للتعريف بأساليب التأديب غير العنيفة وتقديم المعلومات والتوجيه للوالدين (ص 13)."}]},{"t":"الأبوة أكثر من رابط بيولوجي","pg":14,"key":"الأبوة هي أكثر من مجرد بيولوجيا، فهي تتجلى من خلال جودة وعمق رابط الرعاية الذي يربط الرجال بالأطفال.","p":["يؤيد مؤلفو هذا الدليل فكرة أن الأعمام والإخوة والمدرسين والمدربين وأزواج الأمهات قادرون على التمتع بعلاقات إيجابية وثيقة للغاية مع الأطفال."],"items":[{"h":"المشاركة منذ البداية","x":"أي حتى قبل ولادة الطفل، وهي أول موضوعات حملة الأبوة العالمية التي يذكرها الدليل (ص 14)."},{"h":"مجرد اللعب","x":"وقت اللعب مع الطفل من صميم دور الأب."},{"h":"التحلي بالشجاعة في إظهار العاطفة","x":"التعبير عن الحنان للأبناء جزء من الأبوة."},{"h":"التربية من دون عنف ودعم الأم","x":"موضوعان متلازمان في رؤية البرنامج للأب المشارك."}]},{"t":"عقبات أمام الأبوة المنخرطة","pg":16,"key":"وغالبا ما يتأثر هؤلاء الرجال منذ طفولتهم بمواقف وسلوك آبائهم بخصوص تقديم الرعاية.","p":["أن العديد من الرجال الذين أبلغوا عن مشاركتهم في تقديم الرعاية كبالغين كان لديهم على الأغلب مقدمي رعاية أقوياء من نساء ورجال قدموا لهم نموذجا إيجابيا لتقديم رعاية في طفولتهم"],"items":[{"h":"التنشئة والعادات","x":"كثير من التصورات عن دور الرجل مكتسبة من سنوات التنشئة في الأسرة والمدرسة والإعلام (ص 15)."},{"h":"طول ساعات العمل","x":"انشغال الأب خارج البيت لإعالة أسرته يقلل حضوره في حياة أطفاله (ص 15)."},{"h":"قطاع الرعاية الصحية","x":"خدمات الأمومة والطفولة موجهة في الغالب إلى الأم، ولا تحسب حساب الأب (ص 16)."},{"h":"أنظمة العمل والإجازات","x":"إجازة الأبوة نادرة، وبعض المستشفيات لا تسمح للأب بمرافقة زوجته (ص 16)."},{"h":"الإشراك المبكر","x":"«يعتبر التواصل مع الآباء من خلال برامج تشجع هذا الانخراط المبكر في حياة أطفالهم (بما في ذلك فترة ما قبل ولادة الطفل) حيوي لأن مستويات انخراط الأب في مراحل مبكرة تميل إلى الاستمرار» (ص 18)."}]}],"quiz":[{"q":"لماذا يركز الدليل على إشراك الأب في المراحل الأولى من حياة طفله؟","o":["لأن انخراطه المبكر يميل إلى الاستمرار","لأن تعلق الطفل بأبيه ينتهي بعد سنته الأولى","لأن المستشفيات تشترط حضوره في كل زيارة","لأن دوره بعد السنة الرابعة يصبح ثانويا"],"why":"يعتبر التواصل مع الآباء من خلال برامج تشجع هذا الانخراط المبكر في حياة أطفالهم (بما في ذلك فترة ما قبل ولادة الطفل) حيوي لأن مستويات انخراط الأب في مراحل مبكرة تميل إلى الاستمرار","pg":18},{"q":"بحسب الدليل، من يستطيع بناء علاقة إيجابية وثيقة مع الطفل غير أبيه البيولوجي؟","o":["الأعمام والإخوة والمدرسون والمدربون","الأم والجدة وحدهما في السنوات الأولى","المختصون في الرعاية الصحية فقط","لا أحد، فالرابط البيولوجي شرط أساسي"],"why":"يؤيد مؤلفو هذا الدليل فكرة أن الأعمام والإخوة والمدرسين والمدربين وأزواج الأمهات قادرون على التمتع بعلاقات إيجابية وثيقة للغاية مع الأطفال.","pg":14},{"q":"ما الرسالة الخفية التي يتعلمها الطفل حين يعاقب بعنف؟","o":["أن القوة وسيلة مقبولة لحسم الخلاف","أن والده يحبه ويخاف على مستقبله","أن الخطأ لا يتكرر إذا كان العقاب شديدا","أن احترام الكبار يقوم على الطاعة وحدها"],"why":"كذلك، يعلم الأطفال أن العنف هو استراتيجية مقبولة ومناسبة لحل النزاعات واكتساب أفضلية على الآخر.","pg":13},{"q":"ما الذي ميز في طفولتهم الرجال الذين يشاركون اليوم في رعاية أبنائهم؟","o":["من قدم لهم نموذجا إيجابيا في الرعاية","حصولهم على تعليم جامعي في سن مبكرة جدا","نشأتهم في أسر صغيرة قليلة عدد الأولاد","عملهم في وظائف ذات ساعات عمل قصيرة"],"why":"أن العديد من الرجال الذين أبلغوا عن مشاركتهم في تقديم الرعاية كبالغين كان لديهم على الأغلب مقدمي رعاية أقوياء من نساء ورجال قدموا لهم نموذجا إيجابيا لتقديم رعاية في طفولتهم","pg":16},{"q":"صديق يقول إن حضور الأب في الحمل لا يغير شيئا. بماذا ترد عليه من الدليل؟","o":["مشاركته ضرورية لصحة الأم والطفل","حضوره مفيد للأب نفسه دون أثر على الأم","دوره يبدأ فعليا بعد دخول الطفل المدرسة","مشاركته مهمة في الولادة الأولى فقط"],"why":"تعتبر مشاركة الآباء ومقدمي الرعاية الذكور غير العنيفة خلال فترة ما قبل الولادة وبعدها ضرورية جدا لصحة الأم والطفل ورفاههما.","pg":10}],"scene":{"t":"أب يرى دوره في الإنفاق فقط","x":"أب منشغل بعمله يقول لزميله: دوري أن أؤمن المال، والتربية والرعاية شأن البيت. ماذا ينصحه الدليل؟","opts":["يحرص على حضور فعلي في حياة أطفاله منذ البداية، لأن ذلك ينفعهم ويطيل أثره","يكتفي بالإنفاق ويترك كل ما يخص الأطفال لأمهم","يؤجل مشاركته حتى يكبر الأطفال ويصيروا قادرين على الحوار"],"why":"وقد أظهرت عقود من الدراسات أن الأطفال الذين يجدون في آبائهم قدوة تقدم الدعم والحنان، سيتمتعون على الأرجح بمستويات أعلى من السلامة وحماية أفضل من العنف وبمستقبل أكثر نجاحا","pg":6}},{"k":"c2","t":"القسم الأول: الأبوة في قطاع الرعاية الصحية (الحمل والولادة)","q":"كيف يشرك العاملون الصحيون الأب في متابعة الحمل والولادة؟","essence":"العيادة بوابة لإشراك الأب مبكرا","kw":["الرعاية السابقة للولادة","غرفة الولادة","الاتصال الجسدي"],"sections":[{"t":"قطاع الصحة نقطة دخول","pg":21,"key":"قطاع الصحة هو نقطة دخول أساسية لدعم الإشراك المبكر للوالدين في تقديم الرعاية.","p":["عند تواجد الرجال في قاعة الاستشارة، يجب تشجيعهم على مواصلة إنخراطهم."],"items":[{"h":"توجيهات أوضح","x":"يحتاج القطاع الصحي إلى بروتوكولات واضحة حول سبل العمل مع الآباء (ص 22)."},{"h":"مواد تثقيفية في قاعة الانتظار","x":"حملات ومواد تشجع مشاركة الرجال في الأبوة (ص 22)."},{"h":"حين يغيب الأب","x":"يشجع المختص الأم على إحضاره، بشرط أن تكون العلاقة غير عنيفة ومشاركته ممكنة (ص 22)."}]},{"t":"مع الأب في زيارات متابعة الحمل","pg":25,"key":"إشراك الأب بفعالية خلال الاستشارة من خلال طرح أسئلة عليه والإجابة على أي سؤال يراوده.","p":["تشجيع الأب على التواصل مع الجنين في رحم الأم من خلال لمس أو تدليك بطن الأم والتحدث إلى الجنين"],"items":[{"h":"الاتصال البصري","x":"يوجه المختص نظره وحديثه إلى الأب والأم معا، ويعامل الأب شريكا لا مرافقا ثانويا (ص 25)."},{"h":"الدعم العاطفي والعملي","x":"تحفيز الأب على تقديم العاطفة والتعاطف، وتحمل نصيبه من المهام المنزلية خلال الحمل (ص 25)."},{"h":"التواصل مع الجنين","x":"تشجيع الأب على التحدث إلى الجنين ولمس بطن الأم (ص 25)."},{"h":"حالات الطوارئ","x":"إطلاع الوالدين على العلامات التي تشير إلى ولادة طارئة، وتزويدهما بخطوات التحرك (ص 25)."},{"h":"مساحة آمنة للهواجس","x":"منح الوالدين وقتا كافيا للتعبير عن مخاوفهما: الصحية والمالية ومسائل العمل (ص 25)."},{"h":"إذا جاءت الأم وحدها","x":"يسأل المختص عن الأب، ويبحث معها سبل حضوره، ويحترم قرارها إن عارضت مرافقته (ص 24)."}]},{"t":"قبل الولادة وأثناءها وبعدها","pg":29,"key":"أصبحنا نفهم الآن أن ولادة الطفل هي فرصة أساسية لإنشاء روابط عاطفية بين الأب وطفله.","p":["وهنا يمكن للآباء لعب دور مهم في تنظيم درجة حرارة جسد المولود الجديد وفي استقرار وظائف الرئتين والقلب."],"items":[{"h":"تعليمات محددة للأب","x":"مثل مساعدة الأم على توضيب حقيبتها، والاستماع الفاعل إلى مخاوفها (ص 30)."},{"h":"التحضير لغرفة الولادة","x":"إخبار الأب بما يتوقعه هناك، وكيف يساعد الأم على التنفس ويشجعها (ص 30)."},{"h":"بعد الولادة مباشرة","x":"إشراك الأب مع طفله بأسرع وقت، وشرح كيفية حمل المولود إن كان طفله الأول (ص 30)."},{"h":"الولادة القيصرية","x":"حين لا تستطيع الأم احتضان طفلها فورا، يمكن للأب أن يوفر له الاتصال الجسدي المباشر (ص 30)."}]},{"t":"عند الخروج من المستشفى","pg":31,"key":"إطلاع الأب والأم على سبل الاعتناء بالمولود الجديد والتأكد من مغادرتهما مع مواد تحتوي على معلومات يحتاجان إليها.","p":[],"items":[{"h":"الكشف الطبي للطفل","x":"إطلاع الأب على أهميته، وتحديد موعد ومكان أول كشف للمولود وتشجيعه على حضوره (ص 31)."},{"h":"اكتئاب ما بعد الولادة","x":"تعريف الأب بعوارضه وسبل مساعدة الأم على التعامل معه (ص 31)."},{"h":"تسجيل المولود","x":"كيفية تسجيل الطفل في السجل المدني واستخراج شهادة الميلاد (ص 31)."},{"h":"دعم البيت","x":"يستطيع الأب دعم الأم والطفل بطرق كثيرة، منها القيام بالأعمال المنزلية والاعتناء بالطفل (ص 31)."}]},{"t":"قائمة تقييم العيادة","pg":27,"key":"تم تصميم القائمة المرجعية لمساعدة اختصاصيي الرعاية الصحية على تحديد مجالات في أنظمتهم تحتاج إلى تحسين والعمل عليها.","p":[],"items":[{"h":"كرسي للأب","x":"توفير مساحة للأب المرافق، مثل كرسي إضافي في غرفة الاستشارة (ص 27)."},{"h":"دوام مناسب","x":"دوام مطول من أجل الآباء العاملين (ص 27)."},{"h":"مواد للآباء","x":"مواد تثقيفية عن الوالدية خاصة بالآباء، وورش عمل للآباء المرتقبين (ص 27)."},{"h":"تسجيل الحضور","x":"تسجيل حضور الأب في كل موعد لمتابعة مدى إشراكه (ص 27)."}]}],"quiz":[{"q":"لماذا يعد موعد التصوير بالموجات فوق الصوتية لحظة خاصة لإشراك الأب؟","o":["لأنه يرى طفله على الشاشة ويسمع نبض قلبه","لأن الطبيب يحتاج توقيعه على نتائج الفحص","لأنه الموعد الوحيد الذي يسمح فيه بالحضور","لأنه يحدد فيه موعد الولادة مع الطبيب"],"why":"تعتبر الزيارة الخاصة بإجراء الصورة بالموجات فوق الصوتية خلال الحمل، فرصة فريدة للآباء لمشاهدة طفلهم على شاشة والاستماع إلى دقات قلبه.","pg":23},{"q":"جاءت أم وحدها إلى موعد المتابعة ورفضت مرافقة زوجها لها. ما الذي يوصي به الدليل؟","o":["احترام قرارها مع الانتباه لأي مؤشر مقلق","الإصرار على حضوره لأنه حق ثابت للطفل","الاتصال بالأب مباشرة لإقناعه بالحضور","تأجيل الموعد إلى أن يتمكن الأب من الحضور"],"why":"في حال عارضت الأم مرافقة الأب لها، يجب احترام قرارها.","pg":24},{"q":"ما الدور الذي يستطيع الأب أداءه عند الولادة القيصرية بحسب الدليل؟","o":["تنظيم حرارة المولود بالتلامس المباشر","إرضاع المولود بالحليب الصناعي فورا","متابعة الإجراءات الإدارية خارج القسم فقط","انتظار خروج الأم من غرفة العمليات أولا"],"why":"وهنا يمكن للآباء لعب دور مهم في تنظيم درجة حرارة جسد المولود الجديد وفي استقرار وظائف الرئتين والقلب.","pg":30},{"q":"كيف ينبغي أن يعامل المختص الأب الحاضر في الاستشارة؟","o":["شريكا يوجه إليه السؤال ويجاب عنه","مستمعا يجلس بصمت حتى انتهاء الفحص","مرافقا ينتظر في قاعة الانتظار الخارجية","ناقلا يبلغ الأم بالتعليمات بعد الزيارة"],"why":"إشراك الأب بفعالية خلال الاستشارة من خلال طرح أسئلة عليه والإجابة على أي سؤال يراوده. معاملته كشريك متساو وليس كشخص يلعب دورا ثانويا.","pg":25},{"q":"أي معلومة يعدها الدليل مهمة للأب عند مغادرة المستشفى بعد الولادة؟","o":["علامات اكتئاب ما بعد الولادة لدى الأم","طريقة اختيار روضة الطفل في المستقبل","أنواع الحليب الصناعي الأنسب للمولود","مواعيد زيارات الأقارب للمولود في البيت"],"why":"عوارض الاكتئاب اللاحق للولادة وسبل مساعدة الأم على التعامل معه","pg":31}],"scene":{"t":"موعد متابعة يتعارض مع العمل","x":"زوجتك حامل ولديها موعد متابعة صباح الأحد، ووقته يتعارض مع دوامك. ماذا تفعل بحسب الدليل؟","opts":["تخطط مسبقا لتغيير جدول عملك أو أخذ استراحة أطول لتحضر معها","تطلب منها الذهاب وحدها وتسألها عن النتائج مساء","تعتذر عن الحضور لأن المتابعة شأن الأم والطبيب"],"why":"في حال كانت الأم راغبة في أن يرافقها أب الطفل، النظر معها في سبل دعوته والخطوات الضرورية لكي يكون حضوره ممكنا (على سبيل المثال التخطيط المسبق بحيث يتمكن من أخذ إستراحة غداء أطول أو تغيير جدول عمله).","pg":24}},{"k":"c3","t":"توصيات الرعاية الصحية للأطفال من 0 إلى 4 سنوات","q":"كيف يرعى الأب صحة طفله الصغير ويؤدبه دون عنف؟","essence":"الثقة أولا، والتأديب الإيجابي بلا عنف","kw":["بناء الثقة","التأديب الإيجابي","متابعة صحة الطفل"],"sections":[{"t":"بناء الثقة في الأشهر الأولى","pg":34,"key":"تكمن مهمة مقدمي الرعاية الأهم خلال الأشهر الست الأولى من حياة الطفل في بناء الثقة.","p":["ويتم هذا الأمر من خلال تلبية الاحتياجات الجسدية للطفل (على غرار تأمين الغذاء والمياه وتخفيف الألم) وتوفير الراحة الجسدية والعاطفية (على غرار الإمساك والهز والحمل).","هذا التعلق هو أساس العلاقة بين الأهل والطفل."],"items":[{"h":"لماذا التعلق مهم؟","x":"لأنه أساسي لنمو دماغ الطفل، ويسمح له بالاستكشاف والتعلم حين يشعر بالأمان (ص 34)."},{"h":"الكشوفات الروتينية","x":"فرصة لإطلاع الوالدين على سبل رعاية أطفالهم ودعم نمط حياة صحي للعائلة كلها (ص 34)."}]},{"t":"ما هو التأديب الإيجابي؟","pg":36,"key":"التأديب الإيجابي ليس والدية متساهلة ولا تتمحور حول العقاب.","p":["التأديب الإيجابي هو مقاربة للوالدية تعلم الأطفال وتوجه سلوكهم وتحترم في الوقت نفسه حقهم في النمو الصحي والحماية من العنف والمشاركة في التعلم.","العقاب العنيف يخفف من تقدير الذات لدى الأطفال ويتداخل مع عملية التعلم ومع النمو الإدراكي والعاطفي للأطفال."],"items":[{"h":"لماذا يلجأ الآباء إلى العقاب؟","x":"كثيرون يربون كما تربوا، ولحظات الإحباط مع قلة الفهم لنمو الطفل قد تدفع إلى العقاب الجسدي أو العاطفي (ص 35)."},{"h":"أثر الضرب والصراخ","x":"قد يؤدي على المدى الطويل إلى العدائية والقلق والشقاء، ويخلق عقبات في التواصل بين الوالد والطفل (ص 35)."},{"h":"هدف التأديب الإيجابي","x":"حلول طويلة الأمد تنمي الانضباط الذاتي لدى الطفل ومهارات تلازمه مدى الحياة (ص 36)."}]},{"t":"دور الأب في متابعة صحة طفله","pg":37,"key":"إعادة التأكيد على أن الانخراط في صحة الطفل هو مسؤولية كلا الوالدين","p":[],"items":[{"h":"جدول التطعيم","x":"التأكد من معرفة الأب بجدول تلقيح طفله ومراحل نموه النفسية والجسدية (ص 37)."},{"h":"الإصغاء للأب","x":"الاستماع بعناية إلى هواجس الآباء ومخاوفهم وأسئلتهم (ص 37)."},{"h":"مهام يومية","x":"اللعب مع الطفل، وتحميمه، وتغيير حفاضاته، ومساعدته على ارتداء ملابسه، وقراءة القصص له (ص 37)."},{"h":"مواعيد مناسبة","x":"محاولة برمجة المواعيد الطبية بما يناسب أوقات عمل الأب (ص 37)."},{"h":"الأب الذي يأتي وحده","x":"على المختص أن يتذكر أن الأب قادر على المجيء بمفرده مع طفله، وأنه غالبا أب منخرط (ص 37)."}]},{"t":"حين يختلف أسلوب الوالدين","pg":37,"key":"سيتوجب عليهما معا مناقشة طريقة تأديب الطفل من دون استخدام العنف الجسدي أو النفسي.","p":[],"items":[{"h":"الزيارة الصحية فرصة","x":"يمكن أن تكون بداية نقاش بين الوالدين حول أسلوب التربية (ص 37)."},{"h":"طلب الدعم","x":"عند التوتر بسبب اختلاف الأساليب، ينصح الدليل بالاستعانة بالشبكة الاجتماعية للأسرة (ص 37)."},{"h":"الإحالة المتخصصة","x":"توفير معلومات الاتصال بمختصين في الصحة النفسية عند الحاجة (ص 37)."}]}],"quiz":[{"q":"ما المهمة الأهم لمن يرعى الطفل في أشهره الستة الأولى؟","o":["بناء الثقة بتلبية حاجاته وطمأنته","تعليمه النوم وحده في سريره منذ البداية","تعويده على الطعام الصلب في وقت مبكر","ضبط بكائه بتركه حتى يهدأ بنفسه"],"why":"تكمن مهمة مقدمي الرعاية الأهم خلال الأشهر الست الأولى من حياة الطفل في بناء الثقة.","pg":34},{"q":"أي وصف يطابق التأديب الإيجابي كما يعرفه الدليل؟","o":["توجيه للسلوك يحترم حق الطفل","تساهل يترك للطفل أن يفعل ما يريد","نظام عقوبات متدرج يبدأ بالحرمان","مكافآت مادية تقدم مقابل كل طاعة"],"why":"التأديب الإيجابي هو مقاربة للوالدية تعلم الأطفال وتوجه سلوكهم وتحترم في الوقت نفسه حقهم في النمو الصحي والحماية من العنف والمشاركة في التعلم.","pg":36},{"q":"ما أثر العقاب العنيف في الطفل بحسب الدليل؟","o":["يضعف تقديره لذاته ويعيق تعلمه ونموه","يقوي انضباطه إذا جاء بعد الخطأ مباشرة","لا يترك أثرا ما دام قليلا ومتباعدا","يجعله أكثر قربا من والده بعد الندم"],"why":"العقاب العنيف يخفف من تقدير الذات لدى الأطفال ويتداخل مع عملية التعلم ومع النمو الإدراكي والعاطفي للأطفال.","pg":35},{"q":"جاء أب وحده بطفله إلى الكشف الطبي. كيف ينظر إليه المختص بحسب الدليل؟","o":["على الأرجح أب منخرط في رعاية طفله","حالة استثنائية تستدعي السؤال عن غياب الأم","مرافق مؤقت لا يعتمد عليه في التعليمات","شخص يحتاج إذنا مكتوبا من الأم أولا"],"why":"تذكر أن الأب قادر على المجيء بمفرده إلى الزيارة الطبية مع طفله. وهو على الأرجح في هذه الحالة أب منخرط خارج إطار الرعاية الصحية.","pg":37},{"q":"ما الذي يحقق التعلق الآمن بين الطفل ومن يرعاه؟","o":["تلبية حاجاته مع الإمساك والهز والحمل","إطعامه في مواعيد ثابتة بلا احتضان","تركه يبكي حتى يتعلم الاعتماد على نفسه","إبعاده عن الوالدين ساعات طويلة يوميا"],"why":"ويتم هذا الأمر من خلال تلبية الاحتياجات الجسدية للطفل (على غرار تأمين الغذاء والمياه وتخفيف الألم) وتوفير الراحة الجسدية والعاطفية (على غرار الإمساك والهز والحمل).","pg":34}],"scene":{"t":"خلاف على أسلوب التأديب","x":"تصرخ أنت في وجه ابنك ذي الثلاث سنوات حين يخطئ، وزوجتك ترى ذلك مؤذيا، وبدأ الخلاف يتكرر بينكما. ما الذي يقترحه الدليل؟","opts":["تجلسان معا وتتفقان على طريقة تأديب لا عنف فيها، وتطلبان الدعم إن احتجتما","يتمسك كل منكما بأسلوبه ما دام الطفل يطيع في النهاية","تترك التأديب كله لها حتى لا يتكرر الخلاف أمام الطفل"],"why":"سيتوجب عليهما معا مناقشة طريقة تأديب الطفل من دون استخدام العنف الجسدي أو النفسي.","pg":37}},{"k":"c4","t":"القسم الثاني: قبل البدء، إدارة مجموعات الآباء","q":"كيف ينظم الميسر مجموعة آباء آمنة ومثمرة؟","essence":"بيئة آمنة وقواعد واضحة وميسر يصغي","kw":["الميسر","القواعد الأساسية","كسر الجليد"],"sections":[{"t":"لماذا مجموعات الآباء؟","pg":42,"key":"وتوفر الجلسات الجماعية مساحة للرجال لمشاركة مخاوفهم ومناقشة التحديات التي يواجهونها في أدوارهم الوالدية.","p":["إذا صرخ ابني في وجهي، هل علي أن أظهر بصورة صاحب السلطة وأن أصرخ في وجهه وبصوت أعلى ليتعلم كيفية احترامي، أم أنه علي أن أخبره كيف أشعر وأسأله ما المشكلة؟"],"items":[{"h":"التعلم من التجارب","x":"يكتسب كل أب من تجارب الآخرين معلومات عن العلاقات والوالدية وصنع القرارات والموازنة بين العمل والعائلة (ص 42)."},{"h":"حلول متعددة","x":"حتى حين لا توجد إجابة واحدة صحيحة، يساعد سماع حلول مختلفة الآباء على الوصول إلى استنتاجاتهم (ص 42)."}]},{"t":"من هو الميسر؟","pg":43,"key":"ليس الميسر(ة) مدرسا أو معلما. فهو ليس خبيرا في المحتوى، بالرغم من أهمية الخبرة في هذا المجال، بل إنه يخلق بيئة آمنة، ويتحلى بالقدرة على الإصغاء، ولديه رغبة بتشجيع النقاش أكثر من الاستماع إلى نفسه وإطالة الكلام.","p":[],"items":[{"h":"ضبط النزاعات","x":"يحتاج الميسر إلى الكفاءة في السيطرة على الخلافات التي قد تنشأ داخل المجموعة (ص 43)."},{"h":"الانتباه للأفراد","x":"قد يحتاج بعض المشاركين إلى اهتمام خاص بعيدا عن المجموعة، أو إلى إحالة لخدمات استشارية (ص 43)."}]},{"t":"تنظيم الدورة","pg":44,"key":"يوصى بتشكيل مجموعات تتألف من 5 إلى 15 مشاركا.","p":[],"items":[{"h":"عدد الجلسات","x":"دورة مثالية من 11 جلسة، معدل كل منها ساعتان أسبوعيا (ص 46)."},{"h":"الفاصل بين الجلسات","x":"فترة استراحة من أيام إلى أسبوع تتيح التفكير وتطبيق ما نوقش في الحياة الواقعية (ص 44)."},{"h":"المشاركون","x":"يفضل البدء مع آباء ينتظرون مولودا، والاستفادة من خبرة من لديهم أطفال (ص 44)."},{"h":"المكان","x":"مكان فسيح مريح هادئ، مع ضيافة خفيفة وملصقات تظهر رجالا يرعون أطفالهم (ص 46)."},{"h":"المرونة","x":"الأنشطة توجيه عام، وللميسر تكييف الأمثلة لتشبه حياة المشاركين (ص 46)."}]},{"t":"القواعد الأساسية للمجموعة","pg":47,"key":"لدى بدء الجلسة الأولى للعمل الجماعي، يوصى بدفع المشاركين إلى وضع «قواعدهم الأساسية» الخاصة، لخلق شعور بالأمان في المجموعة.","p":[],"items":[{"h":"الاحترام","x":"احترام جميع المشاركين، وعدم إهانة الآخرين أو آرائهم (ص 47)."},{"h":"حق الصمت","x":"لكل شخص الحق في التخلي عن دوره في الحديث، ولا يجبر أحد على المشاركة (ص 47)."},{"h":"التحدث بصيغة الأنا","x":"مثل: «أنا أشعر»، «حدث لي أن...» (ص 47)."},{"h":"السرية","x":"لا تناقش تجربة شخص آخر خارج إطار المجموعة (ص 47)."},{"h":"الالتزام","x":"الدقة في المواعيد والحضور الدائم (ص 47)."}]},{"t":"خطوات إدارة كل جلسة","pg":48,"key":"بدء كل جلسة بتسجيل الوصول عبر طرح سؤال عام وبسيط: «كيف حالكم هذا الأسبوع؟»","p":[],"items":[{"h":"البدء في الموعد","x":"احترام وقت الأهل المشغولين (ص 48)."},{"h":"مراجعة الجلسة السابقة","x":"سؤال: هل من أفكار إضافية على موضوعنا الأسبوع الماضي؟ (ص 48)."},{"h":"تقديم الموضوع والأهداف","x":"ثم تنفيذ الأنشطة (ص 48)."},{"h":"الواجب والختام","x":"تذكير بالواجب المنزلي، وجولة سريعة تنقل المجموعة إلى موضوع الجلسة المقبلة (ص 48)."}]},{"t":"ألعاب كسر الجليد وتمارين التنشيط","pg":116,"key":"التنشيط يغير الروتين ويحث الناس على الحركة ويخفف التعب والملل.","p":[],"items":[{"h":"لعبة الأسماء","x":"يقول كل مشارك اسمه ثم يرمي الكرة إلى غيره، على جولتين (ص 114)."},{"h":"ساعي البريد","x":"تبادل معلومات شخصية بطريقة ممتعة عبر تغيير المقاعد (ص 114)."},{"h":"حقيقتان وكذبة","x":"يكتب كل فرد جملتين صحيحتين عن نفسه وجملة خاطئة، والمجموعة تخمن (ص 115)."},{"h":"صوت بقدميك","x":"تقدم خطوة لمن يوافق على عبارة وتراجع خطوة لمن يخالف، ثم يشرح المتطوعون رأيهم (ص 115)."},{"h":"جبل الجليد","x":"ورق صحف يتقلص إلى النصف وعلى الجميع أن يدعم بعضهم ليبقوا فوقه (ص 117)."}]}],"quiz":[{"q":"ما أهم ما يميز الميسر الناجح لمجموعة الآباء؟","o":["يصغي ويشجع النقاش أكثر مما يتكلم","يلقي المحاضرات ويقدم الإجابات الجاهزة","يعرف كل التفاصيل الطبية عن الحمل","يفرض رأيه حين يختلف المشاركون"],"why":"ليس الميسر(ة) مدرسا أو معلما. فهو ليس خبيرا في المحتوى، بالرغم من أهمية الخبرة في هذا المجال، بل إنه يخلق بيئة آمنة، ويتحلى بالقدرة على الإصغاء","pg":43},{"q":"ما العدد الذي يوصي به الدليل لأفراد مجموعة الآباء؟","o":["من 5 إلى 15 مشاركا","من 20 إلى 30 مشاركا","من 2 إلى 4 مشاركين","من 30 إلى 40 مشاركا"],"why":"يوصى بتشكيل مجموعات تتألف من 5 إلى 15 مشاركا.","pg":44},{"q":"لماذا يفضل الدليل أن تفصل بين الجلسات أيام أو أسبوع؟","o":["ليفكروا ويطبقوا ما ناقشوه ثم يعودوا","ليتمكن الميسر من تحضير مواد مطبوعة جديدة","لأن الجلسة الواحدة تحتاج يومين لإكمالها","لتقليل تكاليف المكان والضيافة على المنظمين"],"why":"فهي تتيح للمشاركين الوقت الكافي للتفكير في المواضيع المناقشة وتطبيقها في مواقف حياتية واقعية، ثم العودة إلى المجموعة ومتابعة الحوار.","pg":44},{"q":"مشارك لا يرغب في الحديث عن تجربته في نشاط ما. كيف يتعامل الميسر معه؟","o":["يحترم حقه في التخلي عن دوره","يلزمه بالمشاركة حتى لا يتكرر صمته","يطلب من زملائه إقناعه أمام المجموعة","يستبعده من الجلسة التالية بلطف"],"why":"لكل شخص الحق في التخلي عن دوره في الحديث؛ لا يجبر أحد على المشاركة في أي نشاط أو تمرين.","pg":47},{"q":"أي عبارة تطبق قاعدة التحدث بصيغة الأنا؟","o":["أنا أشعر بالقلق حين يبكي طفلي ليلا","الرجال عادة لا يعرفون رعاية المولود","كلكم تبالغون في الخوف على أطفالكم","يقال إن الأب لا دور له في الرضاعة"],"why":"التحدث دوما بصيغة «الأنا». مثال: إستخدم جملا ك«أنا أشعر»، «حدث لي أن...»","pg":47}],"scene":{"t":"مشارك يستحوذ على الحديث","x":"أنت تيسر جلسة آباء، وأحد المشاركين يطيل في رواية قصته ويأخذ وقت الآخرين. ماذا تفعل؟","opts":["تشكره بلباقة على تجربته ثم تفتح الباب لقصص الآخرين","تقاطعه بحزم وتطلب منه الصمت أمام الجميع","تتركه يكمل حتى النهاية مهما طال الوقت"],"why":"يبدو أنه لديك الكثير من التجارب القيمة لمشاركتها مع المجموعة، وهذا أمر ممتاز! هل لدى الآخرين قصص مماثلة أو مختلفة لمشاركتها؟","pg":64}},{"k":"c5","t":"الجلسة 1: التوقعات","q":"ماذا يحتاج الآباء ويخافون قبل أن يبدأ البرنامج؟","essence":"نبدأ من احتياجات الآباء ومخاوفهم","kw":["احتياجات الأب","من مثلي","الواجب المنزلي"],"sections":[{"t":"أهداف الجلسة","pg":57,"key":"استقاء آراء المشاركين حول احتياجاتهم وتوقعاتهم ودوافعهم.","p":[],"items":[{"h":"الإجابة عن الأسئلة الملحة","x":"استخدام ما يعبر عنه الرجال من احتياجات لتشجيع مشاركتهم (ص 57)."},{"h":"تكييف الجلسات اللاحقة","x":"جمع معلومات من المشاركين لتخطيط الجلسات بحسب حاجة المجموعة (ص 57)."},{"h":"المدة والمواد","x":"ساعتان ونصف، ولوح قلاب وأقلام أو لوح وطبشور (ص 57)."}]},{"t":"نشاط «من مثلي...؟» لكسر الجليد","pg":57,"key":"تشكيل دائرة وجعل المشاركين يقفون.","p":[],"items":[{"h":"الفكرة","x":"ينتقل المشارك إلى وسط الدائرة ويسأل: «من مثلي لديه توأما؟» فينضم إليه كل من يشاركه الحال (ص 57)."},{"h":"الميسر يبدأ","x":"يمكن أن يبدأ الميسر النشاط بسؤاله هو (ص 57)."},{"h":"احترام الاختيار","x":"من لا يرغب في دخول الوسط يحترم خياره (ص 57)."}]},{"t":"النشاط الأساسي: احتياجاتي ومخاوفي كأب","pg":58,"key":"الجزء الأهم في هذا النشاط يكمن في أن تتمكن الأسئلة من دفع أفراد المجموعة إلى مشاركة تجاربهم الخاصة.","p":[],"items":[{"h":"فرق صغيرة","x":"فرق من 3 إلى 4 أشخاص تناقش من 5 إلى 10 دقائق: بأي موضوع ترغبون التفكير، وماذا تودون أن تتعلموا؟ (ص 58)."},{"h":"عرض الأسئلة","x":"متطوع من كل فريق يقدم سؤالين أو ثلاثة، وتسجل على اللوح (ص 58)."},{"h":"الإجابة من الخبرة","x":"يدعى متطوعون للإجابة من تجاربهم: «من يرغب في مشاركة تجربته حول كيفية تمكنه من حل مسألة مماثلة؟» (ص 58)."},{"h":"نقاش جماعي","x":"كيف شعرتم لدى سماع تجارب زملائكم؟ لم يتحدث الرجال قليلا عن مخاوفهم من الأبوة؟ (ص 58)."}]},{"t":"الواجب المنزلي والختام","pg":59,"key":"إن مشاركة التجارب والخبرات مع أهل آخرين تشكل فرصة تعليمية قيمة للرجال المشاركين في هذه الجلسات","p":[],"items":[{"h":"الواجب الأول","x":"التحدث مع الزوجة عن مخاوف تتعلق بالأبوة، وسؤالها عما تتوقعه من زوجها كأب، والإصغاء إليها جيدا (ص 59)."},{"h":"الواجب الثاني","x":"إحضار غرض يرتبط بأب المشارك أو بالقدوة الذكورية في حياته، للحديث عنه في الجلسة التالية (ص 59)."},{"h":"تذكير بالسرية","x":"إبقاء كل ما يقال خلال الجلسات ضمن المجموعة (ص 59)."}]},{"t":"فوائد الأب الملتزم","pg":60,"key":"تشكل تجربة المشاركين المواد الخام في عملية التعلم في أي مجموعة.","p":[],"items":[{"h":"للأبناء","x":"يظهر الأبناء الذين لديهم آباء ملتزمون ومحبون أداء أكاديميا أفضل ونموا اجتماعيا وعاطفيا أفضل (ص 60)."},{"h":"للبنات","x":"العلاقة الوثيقة الإيجابية بالأب ترتبط بقدرة البنت لاحقا على خوض علاقات صحية لا عنف فيها (ص 60)."},{"h":"للزوجين","x":"تكون العلاقة الزوجية أسعد حين يتشارك الزوجان مسؤوليات رعاية الطفل (ص 60)."},{"h":"للأب","x":"الآباء الملتزمون يعيشون أطول ويعانون أقل من ارتفاع ضغط الدم وأمراض القلب (ص 60)."}]}],"quiz":[{"q":"ما الغاية الأولى من الجلسة الأولى في البرنامج؟","o":["معرفة احتياجات المشاركين وتوقعاتهم","شرح مراحل نمو الجنين شهرا بعد شهر","تدريب الآباء على تغيير الحفاضات","اختبار معلومات الآباء عن صحة الأطفال"],"why":"استقاء آراء المشاركين حول احتياجاتهم وتوقعاتهم ودوافعهم.","pg":57},{"q":"ما أهم جزء في نشاط «احتياجاتي ومخاوفي كأب»؟","o":["أن تدفع الأسئلة الآباء إلى مشاركة تجاربهم","أن يجيب الميسر عن كل سؤال إجابة نهائية حاسمة","أن تنتهي الفرق من النقاش في دقيقتين","أن يكتب كل أب أسئلته دون أن يقرأها"],"why":"الجزء الأهم في هذا النشاط يكمن في أن تتمكن الأسئلة من دفع أفراد المجموعة إلى مشاركة تجاربهم الخاصة.","pg":58},{"q":"ما المطلوب من الأب في الواجب المنزلي الأول؟","o":["أن يسأل زوجته عن توقعاتها منه ويصغي","أن يقرأ كتابا عن الحمل ويلخصه للمجموعة","أن يزور طبيبا ويسأله عن مراحل الولادة","أن يكتب قائمة بأخطاء أبيه في تربيته"],"why":"سؤال الشريكة عن الطفل والواجبات المتوقع من الشريك توليها كأب، وإمعان الإصغاء إليها.","pg":59},{"q":"لماذا يطلب من المشارك إحضار غرض يرتبط بأبيه؟","o":["ليروي في الجلسة التالية قصته مع أبيه","ليعرض في معرض ختامي لأعمال المجموعة","ليقارن الميسر بين أدوات الأجيال المختلفة","ليتبرع به لأسرة محتاجة باسم المجموعة"],"why":"المجيء بجهوزية تامة إلى الجلسة التالية لإخبار قصة هذا الغرض وعلاقته بالأب.","pg":59},{"q":"ما الذي يعده الدليل المادة الخام للتعلم في أي مجموعة؟","o":["تجارب المشاركين أنفسهم","المحاضرات التي يلقيها الخبير","الكتيبات المطبوعة الموزعة","الأفلام التي تعرض في الجلسة"],"why":"تشكل تجربة المشاركين المواد الخام في عملية التعلم في أي مجموعة.","pg":60}],"scene":{"t":"أب يخجل من طرح سؤاله","x":"في الجلسة الأولى سأل أب سؤالا بسيطا عن خوفه من حمل المولود، فضحك بعضهم. كيف يتصرف الميسر؟","opts":["يثني على السؤال ويقول إنه مهم، ثم يدعو من مر بالتجربة ليشارك خبرته","يتجاوز السؤال سريعا حتى لا يحرج السائل أكثر","يجيب بنفسه إجابة مختصرة وينتقل إلى النشاط التالي"],"why":"جعل المجموعة تقتدي بالسلوك المطلوب الذي اعتمده الميسر(ة) (استخدام صيغة الأنا، والإثناء على السؤال والقول إنه من المهم طرحه)","pg":58}},{"k":"c6","t":"الجلسة 2: تأثير الأب (ميراث والدي)","q":"ماذا ورثنا عن آبائنا، وماذا نختار أن نورث أبناءنا؟","essence":"نأخذ الجميل من آبائنا ونترك المؤذي","kw":["ميراث الأب","القدوة","الدعم العاطفي"],"sections":[{"t":"أهداف الجلسة","pg":61,"key":"التفكير في الأثر الذي تركه آباء المشاركين أو أي شخصية ذكورية صاحبة سلطة في حياتهم وهم يكبرون.","p":[],"items":[{"h":"الأخذ والترك","x":"مناقشة كيف يأخذ المشاركون الجوانب الإيجابية من تأثير آبائهم، ويعالجون الآثار السلبية حتى لا تتكرر (ص 61)."},{"h":"تمهيد هادئ","x":"لأن النشاط يتطلب انفتاحا عاطفيا، يبدأ بتمرين حركة وتنفس عميق (ص 61)."}]},{"t":"نشاط الغرض والقصة","pg":62,"key":"شيء واحد في أبي أريد أن أطبقه في علاقتي مع أطفالي هو...","p":[],"items":[{"h":"رواية القصة","x":"في جولة دائرية يحكي كل مشارك قصة الغرض الذي أحضره وارتباطه بأبيه (ص 61)."},{"h":"إكمال الجمل","x":"شيء في أبي أريد أن أطبقه مع أطفالي، وشيء في أبي لا أريد تكراره مع أطفالي (ص 62)."},{"h":"سرية الإجابات","x":"على الميسر أن يجعل الإجابات مجهولة الهوية (ص 62)."}]},{"t":"أسئلة النقاش","pg":62,"key":"ما هي الأمور الإيجابية في علاقتك بأبيك والتي ترغب في تطبيقها أو تعليمها لأولادك؟","p":[],"items":[{"h":"ما نتركه خلفنا","x":"ما الأشياء التي تفضل المضي قدما وتركها خلفك وعدم العودة إليها؟ (ص 62)."},{"h":"صور شائعة عن الرجولة","x":"يناقش الدليل عبارات مثل: من المعيب أن يبكي الرجال، ولا يجدر بالرجال التعبير جسديا عن عاطفتهم لأبنائهم كتقبيلهم أو احتضانهم (ص 62)."},{"h":"التخطي","x":"كيف يمكن تخطي الممارسات المضرة لنكون آباء أكثر التزاما في الرعاية؟ (ص 62)."}]},{"t":"الواجب والأفكار الرئيسة","pg":63,"key":"من المهم أن يتكلم الرجال عن علاقتهم بآبائهم، للشفاء والتعلم من تجاربهم، ولتطبيق هذه التوعية الجديدة على أدوارهم الشخصية كآباء.","p":[],"items":[{"h":"الواجب","x":"أن يحدث المشارك شخصا يثق به عن نيته محاكاة أفعال أبيه الإيجابية، وتجنب تكرار التجارب السلبية (ص 63)."},{"h":"الحديث مع الأب","x":"إن رغب المشارك في مناقشة أفكار الجلسة مع أبيه فهذا قراره وحده (ص 63)."},{"h":"رسالة الختام","x":"منح التجربة المؤلمة معنى إيجابيا كفرصة للتطوير الذاتي (ص 63)."}]},{"t":"ملاحظات للميسر: الدعم العاطفي","pg":64,"key":"قد يكون لهذا النشاط تأثير عاطفي جدي على المشاركين والميسرين بسبب تذكر التجارب العنيفة أو غيرها من الأحداث الصادمة","p":["في حال بدأ أحد المشاركين بالانهيار والبكاء أمام المجموعة، لا بد من إظهار تجربته على أنها طبيعية من خلال منحه فسحة للتعبير عن رأيه."],"items":[{"h":"الإصغاء دون حكم","x":"يتحقق الدعم بالإصغاء باحترام دون إطلاق الأحكام أو الضغط (ص 64)."},{"h":"لقاء منفصل","x":"يوضح الميسر استعداده لمحادثة شخصية، ويحيل إلى استشارة نفسية متخصصة عند الحاجة (ص 64)."},{"h":"العناية بالنفس","x":"يوصي الدليل المشاركين بالراحة وشرب الماء بعد الجلسة، فالارتباك بعدها رد فعل طبيعي (ص 64)."}]}],"quiz":[{"q":"ما هدف نشاط «ميراث والدي» في الجلسة الثانية؟","o":["تأمل أثر الأب لنأخذ الجيد ونترك الضار","تقييم أداء آباء المشاركين ومحاسبتهم","جمع قصص طريفة عن الطفولة بهدف التسلية","مقارنة دخل الآباء قديما بدخل الأبناء اليوم"],"why":"مناقشة كيفية أخذ المشاركين للجوانب الإيجابية من تأثير آبائهم، بالإضافة إلى معالجة الآثار السلبية لعدم تكرار الأنماط الضارة عينها.","pg":61},{"q":"مشارك يريد أن يواجه أباه بما تذكره في الجلسة. ماذا يقول له الميسر بحسب الدليل؟","o":["القرار له وحده إن شعر بالحاجة","عليه أن يواجهه حتما ليتعافى من الماضي","يمنع منعا باتا من فتح الموضوع مع أبيه","عليه أن يأخذ إذن المجموعة قبل ذلك"],"why":"إذا عبر مشارك عن رغبته في مناقشة أفكار مناقشات الجلسة مع أبيه، لا بد من إخباره بأن قرارا مماثلا يعود إليه وحده","pg":63},{"q":"بدأ أحد المشاركين بالبكاء أثناء روايته. ما التصرف الذي يوصي به الدليل؟","o":["إظهار تجربته طبيعية ومنحه فسحة","إنهاء الجلسة فورا وتأجيلها إلى أسبوع","الطلب منه الخروج حتى يهدأ ثم يعود","تغيير الموضوع سريعا إلى نشاط مرح"],"why":"في حال بدأ أحد المشاركين بالانهيار والبكاء أمام المجموعة، لا بد من إظهار تجربته على أنها طبيعية من خلال منحه فسحة للتعبير عن رأيه.","pg":64},{"q":"لماذا يرى الدليل أن يتكلم الرجال عن علاقتهم بآبائهم؟","o":["للشفاء والتعلم وتطبيق ذلك في أبوتهم","لإثبات أن جيل الآباء كان أقسى من جيلنا","لتقوية روح المنافسة بين أفراد المجموعة","لتعليم الأبناء تاريخ العائلة وأنسابها"],"why":"من المهم أن يتكلم الرجال عن علاقتهم بآبائهم، للشفاء والتعلم من تجاربهم، ولتطبيق هذه التوعية الجديدة على أدوارهم الشخصية كآباء.","pg":63},{"q":"بماذا يوصي الدليل المشاركين بعد انتهاء جلسة مؤثرة عاطفيا؟","o":["الراحة وشرب الماء وتقبل الارتباك","العودة مباشرة إلى العمل لنسيان ما قيل","كتابة تقرير مفصل عن الجلسة للميسر","الاتصال بالأب فورا والاعتذار منه"],"why":"توصية الجميع بالاعتناء بأنفسهم (وبخاصة فور انتهاء الجلسة)، بأخذ قسط من الراحة، والاستحمام وشرب كمية كافية من الماء.","pg":64}],"scene":{"t":"ذكرى حزام العقاب","x":"أحضر مشارك حزاما كان أبوه يعاقبه به، وحكى قصته بتأثر واضح، وساد صمت في المجموعة. ماذا يفعل الميسر؟","opts":["يشكره على شجاعته وثقته، ويطمئنه بأن كثيرين مروا بتجارب مماثلة","يعلق بأن تلك كانت تربية الزمن الماضي وينتقل إلى غيره","يطلب من المجموعة تحليل تصرف الأب والحكم عليه"],"why":"يمكن القول: «شكرا على شجاعتك وثقتك بنا لمشاركة قصتك هذه. مما لا شك فيه أن كثير من الأشخاص المتواجدين في هذه الغرفة قد مروا بتجارب مماثلة لتجربتك»","pg":64}},{"k":"c7","t":"الجلسة 3: الحمل","q":"كيف يدعم الزوج زوجته الحامل عمليا وعاطفيا؟","essence":"الحمل رحلة يتشاركها الزوجان","kw":["دعم الحامل","قصص الآباء","الخبير الصحي"],"sections":[{"t":"النشاط 1: قصص الوالدية","pg":66,"key":"يؤدي هؤلاء الآباء دور القدوة بالنسبة إلى أعضاء المجموعة.","p":[],"items":[{"h":"الضيوف","x":"يدعى أب أو أكثر شاركوا زوجاتهم منذ الحمل: حضروا الفحوص، ويشاركون في واجبات البيت، ولا يستخدمون العقاب الجسدي (ص 66)."},{"h":"أسئلة للضيف","x":"ما الذي قام به لدعم زوجته؟ ما عوامل الضغط على العلاقة أثناء الحمل؟ كيف اكتسب معلوماته عن الحمل؟ (ص 66)."},{"h":"بديل","x":"إن تعذرت الدعوة تقرأ قصة واقعية لأب مشارك (ص 66)."},{"h":"نقاش","x":"كيف يؤثر الحمل على جودة العلاقة بين الزوجين؟ وكيف تعود إلى البيت وتحدث زوجتك عما سمعت؟ (ص 66)."}]},{"t":"النشاط 2: أبي يستطيع القيام بأي شيء","pg":67,"key":"وبعد تجهيز اللائحة، يحين وقت سؤال الآباء عن الأدوار التي يمكنهم تأديتها لدعم الأم في كل من تلك المهمات والواجبات.","p":[],"items":[{"h":"جدول بعمودين","x":"يكتب في جهة «الأم» وفي الأخرى «الأب»، ويسأل المشاركون: ماذا يمكن للنساء القيام به لضمان حمل صحي؟ (ص 67)."},{"h":"ممارسات الحمل الصحي","x":"حضور صفوف ما قبل الولادة، وتناول الطعام المغذي، وشرب الماء، والراحة، والرياضة الخفيفة، وتجنب التدخين، والحد من الكافيين، والعيش في بيت خال من العنف (ص 67)."},{"h":"دور الأب المقابل","x":"طهو الأطباق، وأخذ الأطفال إلى المدرسة، والتنظيف، وتوفير الدعم العاطفي، والذهاب إلى زيارات ما قبل الولادة (ص 68)."},{"h":"الواجب","x":"البحث عن نمو الجنين واحتياجات الحامل، أو تجربة طريقة جديدة لدعم الزوجة (ص 68)."}]},{"t":"الأفكار الرئيسة","pg":69,"key":"يشكل الحمل تجربة فرحة، غير أنه فترة مجهدة ويتخللها ضغط نفسي، بخاصة بالنسبة إلى الوالدين لأول مرة.","p":["من الضروري التحلي بالصبر والتحدث بصراحة حول المسائل التي قد تسبب النزاعات."],"items":[{"h":"بيئة صحية للحامل","x":"يجب أن تعيش الأم في جو صحي جسديا وغذائيا وعاطفيا، وأن تشعر بأنها مدعومة (ص 69)."},{"h":"صور الدعم","x":"جعل الزوجة تشعر بالرعاية، والحديث عن الطفل القادم، ومرافقتها إلى الفحوص، والتخطيط لاستقبال المولود (ص 69)."}]},{"t":"النشاط 3: استشارة خبير صحي","pg":71,"key":"على الآباء القدوم إلى المواعيد مع أسئلة خطية!","p":[],"items":[{"h":"من يدعى","x":"طبيب أو ممرض أو قابلة يؤمن بأهمية دور الأب خلال الحمل وبعده (ص 71)."},{"h":"موضوعات الخبير","x":"أهمية زيارات ما قبل الولادة، والتغيرات الأبرز لدى الأم والجنين، وكيف يدعم الأب صحة الأم، ووقائع حول اكتئاب ما بعد الولادة (ص 71)."},{"h":"بديل","x":"جمع معلومات من مراجع موثوقة أو أدلة طبية من العيادات (ص 71)."}]}],"quiz":[{"q":"بأي صفة يختار الميسر الآباء الضيوف في نشاط «قصص الوالدية»؟","o":["آباء شاركوا زوجاتهم منذ بداية الحمل","آباء لديهم أكبر عدد من الأطفال في الحي","أطباء متخصصون في أمراض النساء","آباء مروا بتجارب طلاق صعبة ومؤلمة"],"why":"لا بد من الحرص، عند اختيارهم، على أن يكونوا ملتزمين بدور الوالدية وقد التزموا به منذ الحمل.","pg":66},{"q":"ما الغرض من جدول «الأم» و«الأب» في نشاط «أبي يستطيع القيام بأي شيء»؟","o":["تحديد ما يقدمه الأب مقابل حاجات الحامل","إثبات أن الحامل لا تحتاج أي مساعدة من زوجها","توزيع المهام بحيث تتولى الأم الأعمال كلها","مقارنة ثقافة الآباء الطبية بثقافة الأمهات"],"why":"وبعد تجهيز اللائحة، يحين وقت سؤال الآباء عن الأدوار التي يمكنهم تأديتها لدعم الأم في كل من تلك المهمات والواجبات.","pg":67},{"q":"كيف يصف الدليل فترة الحمل؟","o":["فرحة لكنها مجهدة ويتخللها ضغط نفسي","فترة هادئة لا تحتاج تغييرا في البيت","مرحلة تخص الأم ولا تمس العلاقة الزوجية","تجربة سهلة إن كانت الولادة الأولى"],"why":"يشكل الحمل تجربة فرحة، غير أنه فترة مجهدة ويتخللها ضغط نفسي، بخاصة بالنسبة إلى الوالدين لأول مرة.","pg":69},{"q":"زوجتك متوترة في حملها وبدأت الخلافات الصغيرة تكثر. ما النصيحة التي يقدمها الدليل؟","o":["الصبر والحديث بصراحة عما يسبب الخلاف","تجنب الحديث تماما حتى تنتهي فترة الحمل","إحالة كل خلاف إلى الأهل ليفصلوا فيه","قضاء وقت أطول خارج البيت لتهدئة الجو"],"why":"من الضروري التحلي بالصبر والتحدث بصراحة حول المسائل التي قد تسبب النزاعات.","pg":69},{"q":"ما النصيحة العملية التي يوجهها الدليل للآباء قبل موعد الطبيب؟","o":["أن يحضروا معهم أسئلتهم مكتوبة","أن يتركوا الأسئلة للأم وحدها","أن يبحثوا عن طبيب آخر للمقارنة","أن يكتفوا بقراءة التقرير بعد الموعد"],"why":"على الآباء القدوم إلى المواعيد مع أسئلة خطية!","pg":71}],"scene":{"t":"حامل منهكة وأطفال في البيت","x":"زوجتك في الشهر الثالث من الحمل، متعبة طوال اليوم، ولديكما طفلان في المدرسة. ما الذي يقترحه الدليل؟","opts":["تتولى جزءا من الطهي والتنظيف وتوصيل الطفلين، وترافقها إلى الفحوص","تطلب منها أن ترتاح وتترك شؤون البيت حتى تتحسن من تلقاء نفسها","تستعين بأحد الأقارب وتبقى أنت بعيدا عن تفاصيل البيت"],"why":"يمكن للرجال أن يكونوا شركاء داعمين عبر المشاركة في الأعمال المنزلية كالطهي، والتنظيف، ورعاية الأطفال الموجودين في المنزل (كاصطحابهم إلى المدرسة، قراءة القصص لهم...) ومرافقة الأم إلى الزيارات الطبية قبل الولادة.","pg":68}},{"k":"c8","t":"الجلسة 4: الولادة","q":"كيف يستعد الأب ليكون سندا لزوجته يوم الولادة؟","essence":"سند جسدي ومعنوي للأم يوم الولادة","kw":["المخاض","حقيبة الأب","تمارين التنفس"],"sections":[{"t":"أهداف الجلسة","pg":72,"key":"مشاركة الأفكار والتجارب حول دور الأب خلال الولادة، وتحضير الأب لدوره كمرافق للأم.","p":[],"items":[{"h":"معالجة المخاوف","x":"الحديث عن مخاوف الرجال حول ولادة الطفل (ص 72)."},{"h":"الروابط مع الطفل","x":"التشديد على أهمية توثيق الروابط الجسدية والنفسية والعاطفية مع الأبناء والبنات (ص 72)."},{"h":"بديل ملائم","x":"إن لم يناسب النشاط مجموعة الرجال وحدهم، يمكن عرض فيلم تثقيفي عن الولادة إذا كانت الثقافة تسمح بذلك (ص 72)."}]},{"t":"نشاط لعب الأدوار في غرفة الولادة","pg":73,"key":"وسوف يحاكون ما يجري في غرفة الولادة عندما تكون المرأة حاضرة للإنجاب.","p":[],"items":[{"h":"الفرق والأدوار","x":"فرق من 3 أشخاص: الأم التي تشارف على الولادة، والقابلة أو الطبيب، والأب (ص 73)."},{"h":"المشهد","x":"«إنها الساعة العاشرة مساء. الشريكة في غرفة الولادة، وهي تتألم لأنها على وشك الولادة» ويمثل المشهد 5 دقائق (ص 73)."},{"h":"أسئلة بعد التمثيل","x":"ما الشعور بأداء دور الزوج الداعم؟ وما الذي يمكن تغييره لو أعيد الدور؟ (ص 73)."},{"h":"إعادة المشهد","x":"يعيد متطوعون التمثيل مستخدمين المعلومات الجديدة عن التنفس والدعم (ص 74)."}]},{"t":"الأفكار الرئيسة","pg":75,"key":"غالبا ما تكون عملية المخاض والولادة مجهدة جسديا بالنسبة إلى الأم. لذا فإن الجانب الأهم من هذه العملية يتمثل في تأمين الدعم الجسدي والمعنوي الذي تحتاجه.","p":[],"items":[{"h":"موافقة الزوجة","x":"على الرجل أن يتحدث مع زوجته عن تواجده في غرفة الولادة ويحصل على موافقتها (ص 75)."},{"h":"أنظمة المستشفى","x":"بعض المستشفيات لا تسمح بدخول الأب، فمن المهم أن يسأل المركز الصحي مسبقا (ص 75)."},{"h":"التلامس مع المولود","x":"مهم للرابط مع الطفل وله فوائد صحية، وإن لم يتح في المستشفى فهو ممكن في البيت (ص 75)."},{"h":"المزاح في غير موضعه","x":"إذا بدأ المشاركون بتبادل الدعابات يذكرهم الميسر بأهمية احترام التجارب العاطفية (ص 75)."}]},{"t":"بمشاركة الأب الكل رابح","pg":76,"key":"يساهم الآباء الملتزمون في تخفيف الضغط النفسي الذي يرافق الأم خلال الحمل.","p":[],"items":[{"h":"للأم","x":"تخوض تجربة ولادة أكثر إيجابية حين يكون الأب حاضرا ومساندا (ص 76)."},{"h":"للطفل","x":"ينمو الرضع الذين لديهم آباء ملتزمون أطفالا ذوي ثقة عالية بالنفس وقادرين على حل النزاعات بلا عنف (ص 76)."},{"h":"للأب","x":"الآباء المشاركون في حياة أطفالهم أكثر سعادة ويتمتعون بصحة أفضل (ص 76)."}]},{"t":"حقيبة الأب وتقنيات تخفيف الألم","pg":77,"key":"على الثنائي تحضير حقيبتهما قبل التوجه إلى المستشفى أو العيادة للولادة.","p":[],"items":[{"h":"طعام وشراب","x":"المخاض قد يأخذ ساعات، فيجهز الأب ما يلزمه ويأكل خارج غرفة الولادة (ص 77)."},{"h":"الجوال","x":"يستخدمه خارج غرفة الولادة تجنبا لإزعاج المرضى وطاقم العمل (ص 77)."},{"h":"الكاميرا","x":"بعد استئذان الزوجة، مع إلغاء الفلاش عند تصوير المولود (ص 77)."},{"h":"ملابس إضافية","x":"لاحتمال البقاء ليلة أو ليلتين في المستشفى (ص 77)."},{"h":"التنفس مع الزوجة","x":"يساعدها على إيقاع منتظم: شهيق من الأنف وزفير أطول من الفم، ويتنفس معها ويمسك يدها (ص 78)."},{"h":"الوضعية والتدليك","x":"تغيير وضعيتها عند ألم أسفل الظهر، وتدليك ظهرها براحتي اليدين (ص 78)."}]}],"quiz":[{"q":"ما أهم ما تحتاجه الأم أثناء المخاض والولادة بحسب الدليل؟","o":["الدعم الجسدي والمعنوي من حولها","الصمت التام وعدم الحديث معها","وجود أكبر عدد من الأقارب حولها","المعلومات الطبية المفصلة عن كل إجراء"],"why":"لذا فإن الجانب الأهم من هذه العملية يتمثل في تأمين الدعم الجسدي والمعنوي الذي تحتاجه.","pg":75},{"q":"قبل أن يقرر الأب حضور الولادة، ما الخطوة التي يشدد عليها الدليل؟","o":["أن يتحدث مع زوجته ويحصل على موافقتها","أن يطلب إذنا خطيا من أهل الزوجة","أن يحضر دورة تمريض معتمدة قبل الولادة","أن يقرر وحده لأنه الأعلم بمصلحتها"],"why":"يجب أن يتحدث الرجال إلى شريكاتهم عن التواجد في غرفة الولادة وأن يحصلوا على موافقتهن.","pg":75},{"q":"كيف يتعامل الأب مع هاتفه الجوال خلال وجوده في قسم الولادة؟","o":["يستخدمه خارج الغرفة إن اضطر لذلك","يبقيه مفتوحا ليصور كل اللحظات بالفيديو","يرد على المكالمات بصوت منخفض فقط","يسلمه لطاقم التمريض حتى يخرج من القسم"],"why":"إذا اضطر لاستعماله، يرجى استخدامه خارج غرفة الولادة، تجنبا لإزعاج المرضى الآخرين، أو التأثير على تركيز طاقم العمل.","pg":77},{"q":"إذا لم يتح التلامس بين الأب والمولود في المستشفى، فما رأي الدليل؟","o":["يمكن تعويضه في البيت فهو ممكن هناك","تضيع الفرصة ولا يمكن تعويضها لاحقا","يكفي أن تحتضنه الأم ولا حاجة للأب","ينتظر الأب حتى يبلغ الطفل سنة كاملة"],"why":"والأخذ بعين الاعتبار أنه إذا لم تكن ملامسة الطفل ممكنة في المستشفى، فهي ممكنة في البيت.","pg":75},{"q":"ما دور الأب في تمارين التنفس أثناء التقلصات؟","o":["يتنفس معها بإيقاع منتظم ويمسك يدها","يطلب منها حبس النفس حتى يمر الألم تماما","يترك التمرين للقابلة لأنه شأن طبي","يعد بصوت مرتفع ليشتت انتباهها"],"why":"على الأب مراقبة الشريكة، والإمساك بيدها أو وضع يديها على كتفيه.","pg":78}],"scene":{"t":"ليلة الولادة","x":"زوجتك في المخاض منذ ساعات، وأنت في القسم والهاتف لا يتوقف عن الرنين بأسئلة الأهل. ماذا تفعل؟","opts":["تبقى بجانبها تساعدها على التنفس، وترد على المكالمات خارج الغرفة عند الضرورة","ترد على كل مكالمة داخل الغرفة حتى لا يقلق الأهل","تخرج للانتظار في السيارة حتى يتصل بك الطاقم"],"why":"لا يمكن للأب استخدام الخلوي في غرفة الولادة، إذا اضطر لاستعماله، يرجى استخدامه خارج غرفة الولادة، تجنبا لإزعاج المرضى الآخرين، أو التأثير على تركيز طاقم العمل.","pg":77}},{"k":"c9","t":"الجلسة 6: تقديم الرعاية","q":"هل يستطيع الأب رعاية طفله الرضيع بنفسه؟","essence":"الرعاية مهارة يتقنها الأب بالممارسة","kw":["رعاية الرضيع","الحفاضة","الرضاعة الطبيعية"],"sections":[{"t":"أهداف الجلسة","pg":84,"key":"التعرف إلى احتياجات الرعاية لدى الطفل والتفكير مليا في قدرة الرجال على تلبية هذه الاحتياجات.","p":[],"items":[{"h":"مراجعة الفكرة الشائعة","x":"التشكيك في الصورة النمطية التي ترى المرأة بطبيعتها أقدر على رعاية الطفل (ص 84)."},{"h":"المواد","x":"دمى أطفال بحفاضات حقيقية أو وسائد، وموسيقى هادئة (ص 84)."}]},{"t":"تمرين الدمى: تغيير الحفاضة وحمل الطفل","pg":88,"key":"يجب دائما الإمساك بظهر الطفل ورأسه عند حمله، إذ أن رقبة الطفل تعجز عن حمل الرأس بمفردها لحوالي الثلاثة أشهر الأولى.","p":[],"items":[{"h":"غسل اليدين","x":"بالصابون والماء الفاتر قبل التغيير وبعده (ص 88)."},{"h":"تجهيز المكان","x":"التأكد من وجود كل المواد وسلة المهملات في متناول اليد، والحفاظ على اتصال جسدي دائم بالطفل (ص 88)."},{"h":"التنظيف","x":"بمناشف مبللة من الأمام إلى الخلف، ومنشفة نظيفة في كل مرة (ص 88)."},{"h":"طريقة الحمل","x":"يد على الظهر وأخرى على الرأس، ثم يستلقي الجسم على الذراع والرأس في ثنية الساعد (ص 88)."},{"h":"تنبيه","x":"الطفل الحقيقي أكثر حركة من الدمية، فيلزم الحذر (ص 85)."}]},{"t":"أسئلة النقاش","pg":85,"key":"تخيل هذه الحالة: إنها الساعة الثانية صباحا. طفلك يبكي وأنت غير متأكد من السبب، شريكتك منهكة لأنها كانت ترضع الطفل طوال الليل والنهار.","p":[],"items":[{"h":"لماذا يقل إسهام الآباء؟","x":"ما الذي يصعب على الآباء المشاركة في رعاية الرضع؟ (ص 85)."},{"h":"الغضب","x":"هل يمكن أن يغضب المرء من الطفل؟ ماذا تفعل في حالة الغضب؟ وما الخيارات؟ (ص 85)."},{"h":"خطوة عملية","x":"سم شيئا أو شيئين يمكنك القيام بهما لتشارك أكثر في رعاية رضيعك (ص 85)."},{"h":"دعم الرجال لبعضهم","x":"كيف يمكن للرجال أن يدعم بعضهم بعضا في دورهم في رعاية الطفل؟ (ص 85)."}]},{"t":"الأفكار الرئيسة","pg":86,"key":"إن أهم خطوة يقوم بها أحد الوالدين هي توفير الدفء من خلال العاطفة الجسدية (مثل المعانقة وهدهدة الطفل) وبذل أقصى الجهود لمعرفة ما يحتاجه الطفل.","p":["على الآباء تكريس 30 دقيقة على الأقل يوميا لطفلهم."],"items":[{"h":"لماذا يبكي الأطفال؟","x":"لا يستطيعون التعبير بالكلمات، وأحيانا لا يعرفون لماذا يبكون (ص 86)."},{"h":"وقت يومي ممتع","x":"يجب على الرجل أن يقضي وقتا ممتعا مع طفله يوميا: إطعامه وتنظيفه والغناء له وهدهدته وإلباسه (ص 87)."},{"h":"المهمة","x":"ممارسة طريقة جديدة لرعاية الطفل، كغسل ملابسه، وطلب المساعدة إن جهل الأب كيفيتها (ص 86)."}]},{"t":"دور الأب في الرضاعة الطبيعية","pg":89,"key":"قد يشعر بعض الآباء بالإقصاء إذا ما كانت شريكتهم تقوم بإرضاع المولود الجديد، ولكن هناك طرقا عديدة تستطيع من خلالها مساعدة شريكتك على العناية بطفلك","p":[],"items":[{"h":"المساعدة في البيت","x":"المساعدة في الأعمال المنزلية والطبخ (ص 89)."},{"h":"تنظيم الزيارات","x":"الحد من عدد الزوار ووقت الزيارة، فالأم الجديدة بحاجة إلى كثير من الراحة (ص 89)."},{"h":"العناية بالطفل","x":"تحميمه وإلباسه وتغيير حفاضته، والغناء والتحدث إليه، وإحضاره إلى أمه حين يبحث عن الرضاعة (ص 89)."},{"h":"الطمأنة والفخر","x":"التعبير للزوجة عن الفخر بها وطمأنتها حين تقلق من قلة الحليب (ص 89)."},{"h":"فوائد للطفل","x":"حليب الأم أسهل هضما، ويحتوي على مضادات للالتهابات، ومكونات تعزز نمو الدماغ (ص 90)."},{"h":"فوائد للأم والأسرة","x":"تساعد الرحم على العودة لحجمه، وتقلل خطر بعض السرطانات، وتوفر المال (ص 90)."}]}],"quiz":[{"q":"ما أهم خطوة يقوم بها الوالد حين يبكي طفله الرضيع؟","o":["الدفء والاحتضان ومعرفة حاجته","تركه وحده حتى يتعود على الهدوء","إعطاؤه الماء فورا لتهدئته","رفع الصوت قليلا ليتوقف عن البكاء"],"why":"إن أهم خطوة يقوم بها أحد الوالدين هي توفير الدفء من خلال العاطفة الجسدية (مثل المعانقة وهدهدة الطفل) وبذل أقصى الجهود لمعرفة ما يحتاجه الطفل.","pg":86},{"q":"ما الحد الأدنى من الوقت اليومي الذي يقترحه الدليل للأب مع طفله؟","o":["30 دقيقة على الأقل يوميا","ساعتان كاملتان كل يوم","10 دقائق قبل النوم فقط","يوم واحد في نهاية الأسبوع"],"why":"على الآباء تكريس 30 دقيقة على الأقل يوميا لطفلهم.","pg":87},{"q":"لماذا يجب سند رأس الرضيع دائما عند حمله؟","o":["لأن رقبته لا تحمل رأسه في أشهره الأولى","لأن رأسه يبقى أثقل من جسمه حتى سن المدرسة","لأن ذلك يساعده على النوم بسرعة أكبر","لأن ذلك يمنع البكاء عند الرضاعة ليلا"],"why":"يجب دائما الإمساك بظهر الطفل ورأسه عند حمله، إذ أن رقبة الطفل تعجز عن حمل الرأس بمفردها لحوالي الثلاثة أشهر الأولى.","pg":88},{"q":"يشعر أب بأنه مهمش لأن زوجته ترضع المولود. ماذا يقترح الدليل؟","o":["يساعد في البيت ويعتني بالطفل ويقلل الزوار","يقترح الحليب الصناعي ليشارك في الإطعام","ينتظر حتى الفطام ليبدأ دوره الحقيقي مع طفله","ينشغل بعمله لأن دوره سيأتي لاحقا"],"why":"قد يشعر بعض الآباء بالإقصاء إذا ما كانت شريكتهم تقوم بإرضاع المولود الجديد، ولكن هناك طرقا عديدة تستطيع من خلالها مساعدة شريكتك على العناية بطفلك","pg":89},{"q":"ما الاتجاه الصحيح لتنظيف الطفل عند تغيير الحفاضة؟","o":["من الأمام إلى الخلف","من الخلف إلى الأمام","بحركة دائرية متكررة","بمنشفة واحدة لكل المراحل"],"why":"إستعمال مناشف مبللة لتنظيف الطفل من الأمام إلى الخلف.","pg":88}],"scene":{"t":"بكاء في الثانية فجرا","x":"الساعة الثانية فجرا، طفلك يبكي ولا تعرف السبب، وزوجتك منهكة من الإرضاع طوال اليوم، وعندك دوام بعد ساعات. ماذا تفعل؟","opts":["تحمله وتهدهده وتتفقد حاجته لتريح زوجتك قليلا","توقظ زوجتك لأنها أعلم بما يحتاجه الطفل","تنتقل إلى غرفة أخرى لتنام استعدادا للعمل"],"why":"إن أهم خطوة يقوم بها أحد الوالدين هي توفير الدفء من خلال العاطفة الجسدية (مثل المعانقة وهدهدة الطفل) وبذل أقصى الجهود لمعرفة ما يحتاجه الطفل.","pg":86}},{"k":"c10","t":"الجلسة 8: اللاعنف","q":"كيف يكسر الأب حلقة العنف ويدير غضبه في البيت؟","essence":"الغضب شعور، والعنف اختيار يمكن تركه","kw":["حلقة العنف","إدارة الغضب","أساليب التواصل"],"sections":[{"t":"نشاط حبل الغسيل","pg":95,"key":"الطلب من المشاركين وصف تجربتهم الأولى للعنف الأسري خلال طفولتهم على الورقة الأولى.","p":[],"items":[{"h":"ثلاث أوراق","x":"الأولى لتجربة عنف في الطفولة، والثانية للشعور في تلك اللحظة، والثالثة لعنف مارسه المشارك كبالغ (ص 95)."},{"h":"حبلان","x":"يعلق على الأول: عنف شاهدته أو اختبرته، وعلى الثاني: عنف نفذته (ص 95)."},{"h":"دون أسماء","x":"للمشارك أن يرسم أشكالا وألوانا بدل الكتابة، ولا يلزم بكتابة اسمه (ص 95)."},{"h":"سؤال محوري","x":"إذا كان ضحايا العنف أكثر عرضة لارتكابه لاحقا، كيف نكسر هذه الحلقة المفرغة؟ (ص 95)."}]},{"t":"نشاط حل النزاعات بلعب الأدوار","pg":96,"key":"القيام بدور مسرحي لممارسة طرق غير عنيفة للرد في حال الغضب","p":[],"items":[{"h":"المشهد الأول","x":"زوجان يتجادلان حول من يحمم الأطفال، ويتصرفان بتلقائية دون الوصول إلى اتفاق (ص 96)."},{"h":"المشهد الثاني","x":"تمثل المجموعات الموقف نفسه حتى يتوصل الطرفان إلى اتفاق مشترك بطريقة لا عنفية (ص 96)."},{"h":"مواقف إضافية","x":"خلاف حول العمل المنزلي أو رعاية الأطفال، أو خلاف بين أب وابنه (ص 96)."},{"h":"سؤال صريح","x":"غالبا ما نعرف كيف نتجنب النزاع دون عنف، ولكن ذلك لا يحدث أحيانا. لماذا؟ (ص 96)."}]},{"t":"الأفكار الرئيسة","pg":97,"key":"من الممكن فصل الشعور بالغضب عن السلوك العنفي. لا يجب أن يكون الغضب مرادفا للعنف.","p":["إن معظم الرجال قد تعرضوا للعنف خلال طفولتهم وبالتالي فقد تعلموا التعامل مع الخلاف بطريقة عنفية ولكن، وبالرغم من ذلك، فإنه يقع على عاتقهم عدم تكرار هذا العنف.","قد ننجح في السيطرة على غضبنا مع الأشخاص الذين يملكون سلطة علينا (مدير، موظف حكومي الخ....) إلا أننا نطلق العنان لغضبنا مع أقرب أفراد عائلتنا."],"items":[{"h":"الأبناء لا يتحملون ذنبنا","x":"أبناؤنا وبناتنا لا يتحملون ذنب مشاكل أهلهم، ولا يجب أن نطبق تجاربنا السابقة عليهم (ص 97)."},{"h":"الواجب","x":"حديث مع الزوجة والأبناء عن الشعور بالعنف، ووعد داخل الأسرة بحل الخلافات دون عنف (ص 97)."}]},{"t":"أساليب عملية للسيطرة على الغضب","pg":99,"key":"ابتعد عما يثير غضبك، غادر المكان أو قم بنزهة قصيرة.","p":["أنا متضايق لأنك تأخرت. أتمنى لو وصلت في الوقت المحدد أو حذرتني أنك سوف تتأخر."],"items":[{"h":"اهدأ أولا","x":"ابدأ العد إلى 10، تنفس بعمق، تجول أو قم بنشاط بدني (ص 99)."},{"h":"أخبر الطرف الآخر","x":"مثل: «أنا غاضب جدا الآن، وأنا بحاجة إلى الذهاب... عندما أشعر بالهدوء، أرغب في التحدث عن كل هذه المشكلة» (ص 99)."},{"h":"الكلمات بدل الهجوم","x":"عبر عن الغضب بصيغة: «أنا غاضب لأن...» أو «أود منك أن تعرف...» (ص 99)."},{"h":"حاجتي لا موقفي","x":"يفرق الدليل بين «ما الذي أحتاجه» و«ما هو موقفي»، فالتعبير عن الحاجات والتفاوض عليها يحد من التصعيد (ص 98)."}]},{"t":"أساليب التواصل","pg":99,"key":"إن اعتماد أسلوب تواصل فعال هو مفتاح العلاقة والأبوة الناجحة!","p":[],"items":[{"h":"التواصل الوفاقي","x":"طلب ما تريد أو قول ما تشعر به بطريقة صادقة ومحترمة لا تتعدى على حقوق الآخر (ص 99)."},{"h":"التواصل السلبي","x":"التعبير عن الحاجات والمشاعر بطريقة ضعيفة جدا لا تسمع (ص 99)."},{"h":"التواصل العدواني","x":"التعبير بطريقة فيها تهديد أو سخرية أو تحد أو إهانة (ص 99)."}]}],"quiz":[{"q":"ما العلاقة بين الغضب والعنف كما يقررها الدليل؟","o":["يمكن الفصل بينهما، فالغضب غير العنف","العنف نتيجة حتمية لكل غضب شديد","الغضب المكبوت أخطر من العنف الظاهر","لا يمكن ضبط أحدهما دون إلغاء الآخر تماما"],"why":"من الممكن فصل الشعور بالغضب عن السلوك العنفي. لا يجب أن يكون الغضب مرادفا للعنف.","pg":97},{"q":"قال أب: «أبي ضربني، فمن الطبيعي أن أفعل مثله». كيف يرد الدليل؟","o":["عليه ألا يكرر العنف الذي تعلمه","تكرار أسلوب الأب أمر لا يمكن تغييره","الضرب مقبول إذا كان أخف مما تعرض له","يحق له ذلك إن كان الطفل يكرر الخطأ"],"why":"إن معظم الرجال قد تعرضوا للعنف خلال طفولتهم وبالتالي فقد تعلموا التعامل مع الخلاف بطريقة عنفية ولكن، وبالرغم من ذلك، فإنه يقع على عاتقهم عدم تكرار هذا العنف.","pg":97},{"q":"أي عبارة تمثل التواصل الوفاقي حين يتأخر الطرف الآخر عن موعد؟","o":["أنا متضايق لتأخرك، وليتك حذرتني","أنت دائما تتأخر ولا تحترم وقت أحد","لا بأس، لا شيء يهم، افعل ما تريد","إن تأخرت مرة أخرى فلن أنتظرك أبدا"],"why":"قل: «أنا متضايق لأنك تأخرت. أتمنى لو وصلت في الوقت المحدد أو حذرتني أنك سوف تتأخر».","pg":99},{"q":"ما الملاحظة التي يسجلها الدليل عن مكان انفجار غضب كثير من الرجال؟","o":["مع أقرب أفراد العائلة لا مع المدير","في العمل أمام الزملاء أكثر من البيت","مع الغرباء في الطريق والأماكن العامة","مع الأصدقاء أثناء النقاشات الرياضية"],"why":"قد ننجح في السيطرة على غضبنا مع الأشخاص الذين يملكون سلطة علينا (مدير، موظف حكومي الخ....) إلا أننا نطلق العنان لغضبنا مع أقرب أفراد عائلتنا.","pg":97},{"q":"كيف يعرف الدليل التواصل السلبي؟","o":["التعبير عن الحاجة بضعف فلا تسمع","التعبير عن المشاعر بالسخرية والتهديد","طلب ما نريد بصدق واحترام للآخر","الامتناع عن الكلام مدة طويلة عقابا"],"why":"التواصل السلبي: التعبير عن الإحتياجات والمشاعر الخاصة بك بطريقة جد ضعيفة بحيث أنها لا تسمع.","pg":99}],"scene":{"t":"الغضب يتصاعد","x":"عدت من العمل متعبا، فوجدت ابنك قد كسر شاشة الجهاز، وشعرت بالغضب يتصاعد ويدك ترتجف. ماذا تفعل؟","opts":["تبتعد قليلا وتهدأ، ثم تعود لتتحدث معه عما حدث","تعاقبه فورا حتى يعرف أن الخطأ له ثمن","تصرخ بقوة لتفرغ غضبك ثم تنسى الأمر"],"why":"ابتعد عما يثير غضبك، غادر المكان أو قم بنزهة قصيرة.","pg":99}},{"k":"c11","t":"الجلسة 9: احتياجات الأطفال وحقوقهم","q":"كيف نؤدب أطفالنا اليوم بما يخدم صورتهم بعد 20 سنة؟","essence":"التأديب الإيجابي طريق إلى أهداف بعيدة","kw":["طفلي بعد 20 سنة","مراحل النمو","تقنيات التأديب"],"sections":[{"t":"النشاط 1: طفلي بعد 20 سنة","pg":101,"key":"إن مفتاح الانضباط الفعلي هو رؤية التحديات على المدى القصير مثل حمل الطفل على تناول وجبة طعامه أو جمع ألعابه الخ... كفرص للعمل من أجل الأهداف الطويلة الأجل.","p":["يتعلم العديد منا بالغريزة أو بالعودة إلى طريقة تربية أهلنا وتأديبهم لنا."],"items":[{"h":"التخيل","x":"يغمض المشاركون أعينهم ويتخيلون أبناءهم في عيد ميلادهم العشرين: أي نوع من الأشخاص تأمل أن يكون؟ (ص 101)."},{"h":"5 صفات","x":"يحدد كل مشارك صفات يريدها لطفله، مثل: لطيف يحب مساعدة الغير، قادر على اتخاذ القرارات، صادق وجدير بالثقة (ص 101)."},{"h":"أسئلة النقاش","x":"ماذا يعلم الصراخ والضرب الأطفال حول حل النزاعات؟ وكيف يؤثر ذلك على أهدافك البعيدة؟ (ص 101)."}]},{"t":"ثلاثة أسئلة قبل أن تتصرف","pg":102,"key":"هل يفعل الطفل شيئا خاطئا فعلا؟ هل توجد مشكلة ما أو أنك فقدت الصبر فقط؟","p":[],"items":[{"h":"السؤال الأول","x":"إن لم تكن هناك مشكلة، نفس عن غضبك بعيدا عن الطفل (ص 102)."},{"h":"السؤال الثاني","x":"هل يستطيع طفلك حقا القيام بما تتوقعه منه بحسب مرحلة نموه؟ إن لم تكن عادلا فأعد تقييم توقعاتك (ص 102)."},{"h":"السؤال الثالث","x":"هل كان يعلم أنه يخطئ؟ إن لم يكن يعلم فساعده على فهم المتوقع منه وكيف يصلح الخطأ (ص 102)."}]},{"t":"مراحل نمو الطفل بلسانه","pg":105,"key":"أنا أخاف بسهولة، لذا فأنا بحاجة إلى الشعور بالأمان والحماية.","p":[],"items":[{"h":"من الولادة إلى 6 أشهر","x":"يبكي ليعبر عن حاجته، ولا يفهم القواعد بعد، ويحتاج الحب والعاطفة غير المشروطين (ص 105)."},{"h":"من 6 إلى 12 شهرا","x":"يضع الأشياء في فمه ليستكشف، ويبدأ بالأصوات الأولى، وقد يبكي كثيرا مع ظهور أسنانه (ص 105)."},{"h":"من سنة إلى سنتين","x":"مستكشف يبدأ بالكلام والمشي، ونوبات غضبه سببها الإحباط وعجزه عن التعبير (ص 105)."},{"h":"من سنتين إلى 3 سنوات","x":"يبدأ بفهم مشاعره، وقد يخاف الظلام، ويخجل أمام الغرباء (ص 105)."},{"h":"من 3 إلى 5 سنوات","x":"يسأل كثيرا «لماذا؟»، ويحب اللعب الخيالي، ويريد أن يساعد في المهام اليومية ليتعلم (ص 105)."}]},{"t":"تقنيات التأديب الإيجابي","pg":106,"key":"إن نوع التأديب الذي يستخدمه أحد الوالدين يؤثر على شخصية الطفل.","p":[],"items":[{"h":"الإصلاح","x":"إذا كسر لعبة يساعد في إصلاحها، وإذا رمى الألعاب في أنحاء الغرفة يجمعها (ص 106)."},{"h":"التجاهل","x":"يتجاهل الوالد سوء السلوك الذي يهدف إلى جذب الانتباه، ويولي الاهتمام للسلوك الجيد (ص 106)."},{"h":"الحزم","x":"قول المطلوب بوضوح وحزم، والتكلم دائما بلطف حتى عند الحزم (ص 106)."},{"h":"السيطرة على النفس","x":"التصرف قبل أن يخرج الوضع عن السيطرة وقبل أن تغضب (ص 106)."},{"h":"الفصل","x":"عند شجار الأولاد يلعب كل منهم بعيدا عن الآخر فترة حتى يهدأ (ص 106)."},{"h":"إدارة السلوك","x":"الحديث بهدوء لمعرفة سبب الخلاف والتوصل إلى حل مقبول (ص 106)."},{"h":"تغيير طريقة اللعب","x":"إيقاف اللعب الخطر وشرح السبب واقتراح نشاط بديل (ص 106)."},{"h":"الثناء","x":"اهتمام وثناء أكثر للسلوك الجيد وقليل منه للسلوك السيئ (ص 106)."}]},{"t":"الأفكار الرئيسة والمهمة","pg":104,"key":"إن الوالدية هي التزام على المدى الطويل.","p":["على الأهل أن يتحلوا بالصبر، لأن نتائج التأديب الإيجابي قد تستغرق بعض الوقت"],"items":[{"h":"الحماية من العنف","x":"للأطفال الحق في الحماية من جميع أشكال العنف، ومنه العقاب الجسدي أو المهين كالضرب والصراخ (ص 104)."},{"h":"الدفء","x":"الحب غير المشروط والعاطفة اللفظية والجسدية يساعدان الطفل على التعاون ويعلمانه القيم (ص 104)."},{"h":"خطة أبوية","x":"يضع الزوجان خطة تحدد ما يحسنانه، وأساليب التأديب الإيجابي التي سيستعملانها (ص 103)."}]}],"quiz":[{"q":"ما الفكرة التي يقوم عليها نشاط «طفلي بعد 20 سنة»؟","o":["مواقف اليوم فرص لبناء أهداف بعيدة","التخطيط المالي لتعليم الطفل الجامعي","اختيار التخصص الدراسي المناسب للطفل","تخيل المستقبل لتخفيف ضغط الحاضر فقط"],"why":"إن مفتاح الانضباط الفعلي هو رؤية التحديات على المدى القصير مثل حمل الطفل على تناول وجبة طعامه أو جمع ألعابه الخ... كفرص للعمل من أجل الأهداف الطويلة الأجل.","pg":101},{"q":"قبل أن يؤدب الأب طفله، ما أول سؤال يطرحه على نفسه بحسب الدليل؟","o":["هل أخطأ فعلا أم أنني فقدت صبري؟","هل سيكرر الطفل هذا الخطأ مرة أخرى؟","ما العقوبة المناسبة لحجم هذا الخطأ؟","هل رأى أحد من الأقارب ما فعله الطفل؟"],"why":"هل يفعل الطفل شيئا خاطئا فعلا؟ هل توجد مشكلة ما أو أنك فقدت الصبر فقط؟","pg":102},{"q":"رمى طفلك ألعابه في أنحاء الغرفة. أي تقنية من تقنيات التأديب الإيجابي تناسب هذا الموقف؟","o":["الإصلاح بأن يجمعها بنفسه","الحرمان من اللعب أسبوعا كاملا","التوبيخ أمام إخوته ليعتبروا","جمعها عنه بصمت حتى لا يبكي"],"why":"إذا رموا الألعاب في أنحاء الغرفة، اطلب منهم أن يقوموا بجمعها.","pg":106},{"q":"كيف يتعامل الوالد مع سوء سلوك هدفه جذب الانتباه؟","o":["يتجاهله ويهتم بالسلوك الجيد","يعاقبه فورا حتى لا يتكرر منه","يناقشه طويلا في كل مرة يحدث فيها","يكافئه بهدية ليتوقف عن تكراره"],"why":"إن أفضل طريقة للتعامل مع سوء السلوك الذي يهدف إلى جذب اهتمامك هو ببساطة أن تتجاهله. ولكن يجب أن تولي طفلك اهتماما عندما يتصرف بشكل جيد.","pg":106},{"q":"طفل في سنته الثانية تأتيه نوبات غضب متكررة. بم يفسرها الدليل؟","o":["بإحباطه وعجزه عن التعبير بالكلمات","بسوء خلق يحتاج إلى عقاب حازم","بتدليل زائد من الأم في الأشهر الأولى","بنقص في التغذية يحتاج إلى فحص"],"why":"لدي نوبات غضب لأنني أشعر بالإحباط ولا أستطيع التعبير عما أشعر به بالكلمات.","pg":105}],"scene":{"t":"الطفل الذي لا يجمع ألعابه","x":"ابنك ذو الأربع سنوات نثر ألعابه في الصالة ورفض جمعها، والضيوف على وشك الوصول. ماذا تفعل؟","opts":["تطلب منه بحزم ولطف أن يجمعها وتساعده في البداية","تضربه ضربا خفيفا ليتعلم أن العصيان له عاقبة","تجمعها أنت بسرعة وتؤجل الكلام معه إلى وقت آخر"],"why":"عندما يتسبب الأطفال بمشكلة أو عندما يقومون بإلحاق الأذى بطفل آخر، عليهم أن يصلحوا خطأهم أو على الأقل أن يحاولوا المساعدة.","pg":106}},{"k":"c12","t":"الجلستان 10 و11: توزيع مهام الرعاية والتأملات النهائية","q":"كيف يعمل الزوجان فريقا واحدا في البيت؟","essence":"تفاوض وتعاون ووقت مفيد مع الأطفال","kw":["فطيرة الوقت","العمل كفريق","شبكة الأب"],"sections":[{"t":"النشاط 1: عدد الساعات في اليوم","pg":108,"key":"يجب أن يتخيل أن الدائرة هي فطيرة مقطعة إلى شرائح من الزمن وأن الفطيرة بأكملها تعادل نهارا بساعاته الأربع والعشرين.","p":[],"items":[{"h":"فطيرتي","x":"يرسم الأب شرائح العمل والنوم والطعام والترفيه والأعمال المنزلية والوقت مع الأطفال (ص 108)."},{"h":"فطيرة الأم","x":"يرسم فطيرة أخرى كما يتخيل أن زوجته تقسم يومها (ص 108)."},{"h":"أسئلة","x":"كيف تشعر زوجتك حيال توزيع الوقت الحالي؟ لماذا نقلل من قيمة الطبخ والتنظيف ورعاية الأطفال؟ (ص 108)."}]},{"t":"النشاط 2: العمل كفريق واحد","pg":109,"key":"الطلب من بعض المشاركين تمثيل أفراد أسرة يقومون بأعمال منزلية وبرعاية الأطفال.","p":[],"items":[{"h":"المشهد","x":"يبدأ الجميع بالأعمال المنزلية، ثم يتوقف واحد بعد آخر ويوزع عمله على الباقين حتى يبقى واحد يعمل وحده (ص 109)."},{"h":"أسئلة","x":"كيف شعر العامل الأخير؟ وأي هذه المهام تقومون بها فعلا في البيت؟ (ص 109)."},{"h":"أثر القدوة","x":"تشير بعض الأدلة إلى أن الأولاد الذين رأوا آباءهم يشاركون في الأعمال المنزلية أكثر ميلا للقيام بها لاحقا (ص 110)."},{"h":"المهمة","x":"مراقبة توزيع المهام في البيت، ثم تأدية عمل منزلي واحد لا يقوم به الأب أبدا، وملاحظة رد فعل الزوجة (ص 110)."}]},{"t":"الأفكار الرئيسة","pg":111,"key":"إن العدل، والمعني به هنا الإنصاف ضمن الأسرة، لا يعني دائما التساوي في الوقت الذي نمنحه.","p":["إذا كان العمل يمنع الرجال من تكريس وقت أكبر لأطفالهم، يجب أن يتذكروا أن قضاء «الوقت المفيد» مع الأطفال هو ما يهم حقا: مثلا، عليهم أن يتجاهلوا التلفون والتلفزيون عندما يمضون الوقت معهم."],"items":[{"h":"التفاوض والتواصل","x":"الحل في التفاوض والتواصل، والنظر في التزامات كل شخص داخل البيت وخارجه (ص 111)."},{"h":"التدرج","x":"البدء بمهام متفرقة وزيادة الوتيرة مع الوقت، ثم تولي مجموعة مهام مترابطة (ص 111)."},{"h":"بعد قدوم المولود","x":"قد تتغير علاقة الزوجين، وقد يختلفان على التربية، فيتعلم الرجل التفاوض بطريقة لا عنفية لمصلحة الأطفال (ص 111)."}]},{"t":"الجلسة 11: شبكة الأب","pg":112,"key":"سوف يذكر كل فرد في هذا النشاط شيئا تعلمه أثناء وجوده ضمن المجموعة وسوف يطبقه ضمن أسرته.","p":["إن التعبير عن الضعف وتبادل الخبرات ضمن مجموعة هو عمل يتطلب الكثير من القوة."],"items":[{"h":"إكمال الجمل","x":"«سوف أصبح أبا أفضل وأكثر مشاركة...»، «أشعر بالفخر حيال...» (ص 112)."},{"h":"كرة الصوف","x":"يمسك كل فرد طرف الخيط ويرمي الكرة لغيره حتى تتشكل شبكة تمثل خبرات المجموعة (ص 112)."},{"h":"سوار تذكاري","x":"يمكن قطع الشبكة وصنع سوار لكل مشارك (ص 113)."},{"h":"الاستمرار","x":"تبادل وسائل التواصل بإذن الجميع، والاستمرار في اللقاء والدعم (ص 113)."}]}],"quiz":[{"q":"ماذا تمثل الدائرة في نشاط «عدد الساعات في اليوم»؟","o":["يوما كاملا مقسما إلى شرائح من الوقت","دخل الأسرة الشهري موزعا على كل النفقات","عدد أفراد الأسرة ومهام كل منهم","أسبوع العمل وأيام الإجازة فيه"],"why":"يجب أن يتخيل أن الدائرة هي فطيرة مقطعة إلى شرائح من الزمن وأن الفطيرة بأكملها تعادل نهارا بساعاته الأربع والعشرين.","pg":108},{"q":"ما معنى العدل داخل الأسرة كما يوضحه الدليل؟","o":["إنصاف يراعي ظروف كل فرد في الأسرة","تقسيم كل مهمة بالدقيقة بين الزوجين","أن يتولى الأقل دخلا كل الأعمال المنزلية","أن يترك لكل فرد أن يختار ما يريد فقط"],"why":"إن العدل، والمعني به هنا الإنصاف ضمن الأسرة، لا يعني دائما التساوي في الوقت الذي نمنحه.","pg":111},{"q":"أب يعمل ساعات طويلة ويشعر بالذنب لقلة وقته مع أطفاله. بماذا يذكره الدليل؟","o":["بالوقت المفيد معهم بعيدا عن الشاشات","بأن الإنفاق عليهم يعوض غيابه عنهم تماما","بأن يترك عمله حتى يتفرغ لهم كليا","بأن الأطفال لا ينتبهون لغياب الأب"],"why":"إذا كان العمل يمنع الرجال من تكريس وقت أكبر لأطفالهم، يجب أن يتذكروا أن قضاء «الوقت المفيد» مع الأطفال هو ما يهم حقا","pg":111},{"q":"ماذا تمثل الشبكة التي تتكون في نشاط «شبكة الأب»؟","o":["مجموع خبراتهم التي تربطهم معا","شبكة العلاقات المهنية بين الآباء","خريطة لأفراد أسرة كل مشارك","عدد الجلسات التي حضرها كل أب"],"why":"عندما ينتهي الجميع من قول ما تعلموه، سوف تتشكل شبكة. إنها مجموع خبراتهم في هذه المجموعة","pg":113},{"q":"ما المهمة المنزلية التي يطلبها الدليل بعد نشاط العمل كفريق واحد؟","o":["أداء عمل منزلي لا يقوم به الأب عادة","كتابة قائمة بأخطاء الزوجة في التنظيم","شراء أدوات تنظيف جديدة للبيت كله","قياس الوقت الذي تقضيه الزوجة في الهاتف"],"why":"بعد ذلك، عليهم تأدية عمل منزلي واحد لا يقومون به أبدا.","pg":110}],"scene":{"t":"ساعة بعد الدوام","x":"تعود من عملك في السابعة مساء، ولديك ساعة واحدة قبل نوم أطفالك. كيف تقضيها بحسب الدليل؟","opts":["تغلق الهاتف والتلفاز وتمنحهم الساعة كاملة لعبا وحديثا","تجلس معهم وأنت تتابع الأخبار على هاتفك","تؤجل الوقت معهم إلى عطلة نهاية الأسبوع"],"why":"يجب أن يتذكروا أن قضاء «الوقت المفيد» مع الأطفال هو ما يهم حقا: مثلا، عليهم أن يتجاهلوا التلفون والتلفزيون عندما يمضون الوقت معهم.","pg":111}}],"highlights":[{"x":"الأبوة هي أكثر من مجرد بيولوجيا","pg":14},{"x":"تكمن مهمة مقدمي الرعاية الأهم خلال الأشهر الست الأولى من حياة الطفل في بناء الثقة.","pg":34},{"x":"التأديب الإيجابي ليس والدية متساهلة ولا تتمحور حول العقاب.","pg":36},{"x":"تشكل تجربة المشاركين المواد الخام في عملية التعلم في أي مجموعة.","pg":60},{"x":"على الآباء القدوم إلى المواعيد مع أسئلة خطية!","pg":71},{"x":"على الآباء تكريس 30 دقيقة على الأقل يوميا لطفلهم.","pg":87},{"x":"لا يجب أن يكون الغضب مرادفا للعنف.","pg":97},{"x":"إن اعتماد أسلوب تواصل فعال هو مفتاح العلاقة والأبوة الناجحة!","pg":99},{"x":"إن الوالدية هي التزام على المدى الطويل.","pg":104},{"x":"يحتاج الأولاد إلى اهتمامك عندما يحسنون السلوك وليس عندما يسيؤنه.","pg":106},{"x":"إن التعبير عن الضعف وتبادل الخبرات ضمن مجموعة هو عمل يتطلب الكثير من القوة.","pg":113}],"concepts":[{"term":"الأبوة الفاعلة","def":"الآباء الذين يبدون اهتماما فعليا في حياة أطفالهم ويدعمون الأم من خلال المشاركة في تقديم الرعاية وتنفيذ الأعباء المنزلية.","pg":146},{"term":"مقدم الرعاية","def":"هي شخصية أساسية، مثل الشريك أو فرد آخر من الأسرة، تقدم مساعدة مجانية في الاهتمام بشخص ما، سواء كان طفلا صغيرا أم راشدا مقعدا.","pg":146},{"term":"الأعباء المنزلية","def":"هي الأعمال المنفذة بهدف المحافظة على البيت، بما في ذلك إعداد الطعام والتنظيف.","pg":146},{"term":"الأبوة","def":"الرجال الذين يشاركون في نشاطات تقديم الرعاية والمسؤوليات المنزلية بغض النظر إن كانوا الآباء البيولوجيين أم غير البيولوجيين لأطفالهم.","pg":146},{"term":"إجازة أبوة","def":"هي إحدى المنافع التي توفر للرجال إجازة مدفوعة أو غير مدفوعة من العمل كي يساعدوا في رعاية مولودهم الجديد.","pg":147},{"term":"التأديب الإيجابي","def":"التأديب الإيجابي هو مقاربة للوالدية تعلم الأطفال وتوجه سلوكهم وتحترم في الوقت نفسه حقهم في النمو الصحي والحماية من العنف والمشاركة في التعلم.","pg":36},{"term":"التواصل الوفاقي","def":"طلب ما تريد أو قول ما تشعر به بطريقة صادقة ومحترمة بحيث لا تتعدى على حقوق الشخص الآخر أو تقمعه.","pg":99},{"term":"التواصل السلبي","def":"التعبير عن الإحتياجات والمشاعر الخاصة بك بطريقة جد ضعيفة بحيث أنها لا تسمع.","pg":99},{"term":"التواصل العدواني","def":"التعبير عما تريد أو عن مشاعرك بطريقة تنطوي على التهديد، السخرية، التحدي أو الإهانة.","pg":99},{"term":"الإصلاح","def":"عندما يتسبب الأطفال بمشكلة أو عندما يقومون بإلحاق الأذى بطفل آخر، عليهم أن يصلحوا خطأهم أو على الأقل أن يحاولوا المساعدة.","pg":106},{"term":"الفصل","def":"عندما يتخاصم الأولاد مع بعضهم البعض أو يقومون بالضرب والركل والشجار، اجعلهم يلعبون بعيدا عن بضعهم البعض لفترة.","pg":106},{"term":"العنف ضد الطفل","def":"الاستعمال المتعمد للقوة الفيزيائية (المادية) أو القدرة، سواء بالتهديد أو الاستعمال المادي الحقيقي ضد طفل، على يد فرد أو مجموعة، بشكل يؤدي أو يمكن أن يؤدي بنسبة كبيرة إلى أذية حقيقية أو محتملة تؤذي صحة الطفل","pg":148}],"links":[{"topic":"دور الأب في الأسرة","pg":10},{"topic":"العقاب البدني","pg":13},{"topic":"التأديب الإيجابي","pg":36},{"topic":"الحمل ودعم الزوجة","pg":69},{"topic":"الرضاعة الطبيعية","pg":89},{"topic":"الغضب وإدارته","pg":99},{"topic":"التواصل الأسري","pg":99},{"topic":"مراحل نمو الطفل","pg":105},{"topic":"التعاون في الأعمال المنزلية","pg":111},{"topic":"تيسير الحوار في المجموعات","pg":43}]};
